function futureISO(days,hour=10){const d=new Date();d.setHours(hour,0,0,0);d.setDate(d.getDate()+days);return d.toISOString()}
function monthKey(iso){const d=new Date(iso);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function dateText(iso){return new Date(iso).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}
function shortTime(iso){return new Date(iso).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function uid(prefix='id'){return `${prefix}-${(crypto.randomUUID?crypto.randomUUID():Date.now()+Math.random().toString(16).slice(2))}`}
function initials(name='Neighbour'){return name.trim().split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()}
function titleCase(v=''){return v.replace(/\b\w/g,m=>m.toUpperCase())}
function clone(v){return JSON.parse(JSON.stringify(v))}
function moneySafe(v){return esc(v||'Ask for a quote')}
function code4(){return String(Math.floor(1000+Math.random()*9000))}
function normPhone(v=''){return String(v).replace(/\D/g,'')}
function daysUntil(iso){return Math.max(0,Math.ceil((new Date(iso).getTime()-Date.now())/86400000))}

