function icon(name,cls=''){return `<span class="n-icon ${cls}"><svg viewBox="0 0 24 24" aria-hidden="true">${ICON_PATHS[name]||ICON_PATHS.home}</svg></span>`}
function navIcon(name){return `<svg class="nav-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ICON_PATHS[name]||ICON_PATHS.home}</svg>`}
function lookFor(name,label){return `<div class="look-for">${icon(name,'tiny')}<div><small>Look for this in Neighbourly</small><b>${esc(label)}</b></div></div>`}

