function prunePastEvents(s){const now=Date.now();s.events=(s.events||[]).filter(e=>{const d=new Date(e.startsAt);d.setHours(23,59,59,999);return d.getTime()>=now})}
function applyTimedState(s){const now=Date.now();s.promotions=(s.promotions||[]).filter(x=>!x.expiresAt||x.expiresAt>now);(s.accounts||[]).forEach(a=>{if(a.accountStatus==='restricted'&&a.restrictionUntil&&a.restrictionUntil<=now){a.accountStatus='active';a.restrictionUntil=null}});(s.providers||[]).forEach(p=>{if(p.status==='restricted'&&p.restrictionUntil&&p.restrictionUntil<=now){p.status=p.previousStatus==='approved'?'approved':'pending';p.restrictionUntil=null;p.hideFromSearch=p.status!=='approved'}if(p.membershipBreakUntil&&new Date(p.membershipBreakUntil).getTime()<=now){p.membershipBreakUntil=null;p.membershipStatus='active';p.paused=false;p.hideFromSearch=false;p.breakAutoResumedAt=now}if(p.pauseReturn&&!p.membershipBreakUntil){const end=new Date(`${p.pauseReturn}T23:59:59`);if(!isNaN(end)&&end.getTime()<=now){p.pauseReturn=null;p.paused=false;p.hideFromSearch=false}}});(s.requests||[]).forEach(r=>{Object.values(r.safetyTimers||{}).forEach(t=>{if(t.expectedAt&&!t.checkedOut&&new Date(t.expectedAt).getTime()<=now)t.overdue=true})})}
function safeLoad(){
 try{const raw=localStorage.getItem(STORE_KEY);if(!raw){const s=clone(defaultState);prunePastEvents(s);applyTimedState(s);return s}const parsed=JSON.parse(raw);const s={...clone(defaultState),...parsed,ui:{...defaultState.ui,...(parsed.ui||{})},favourites:{...defaultState.favourites,...(parsed.favourites||{})},training:{...(parsed.training||{})},appeals:[...(parsed.appeals||[])],reports:[...(parsed.reports||[])],bannedPeople:[...(parsed.bannedPeople||[])],auditLog:[...(parsed.auditLog||[])]};prunePastEvents(s);applyTimedState(s);return s}catch(e){const s=clone(defaultState);applyTimedState(s);return s}
}
const state=safeLoad();
function persist(){prunePastEvents(state);applyTimedState(state);try{localStorage.setItem(STORE_KEY,JSON.stringify(state));return true}catch(e){toast('We could not save that on this device. Try again.');return false}}
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>toastEl.classList.remove('show'),2500)}
function currentAccount(){return state.accounts.find(a=>a.id===state.currentAccountId)||null}
function currentProvider(){const a=currentAccount();return a?.providerId?state.providers.find(p=>p.providerId===a.providerId):null}
function uniqueProviderId(){let id;do{id='N'+Array.from({length:5},()=>ID_ALPHABET[Math.floor(Math.random()*ID_ALPHABET.length)]).join('')}while(state.providers.some(p=>p.providerId===id)||state.accounts.some(a=>a.providerId===id));return id}
async function hashText(text){if(crypto.subtle){const data=new TextEncoder().encode(text);const hash=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('')}return btoa(unescape(encodeURIComponent(text)))}
function nav(route){state.route=route;state.ui.navOpen=false;persist();render();window.scrollTo({top:0,behavior:'smooth'})}
function signOut(){state.role=null;state.currentAccountId=null;state.route='publicHome';persist();render();toast('Signed out — see you soon ')}

function roleNav(){
 if(state.role==='customer')return [['customerHome','home','Home'],['findHelp','explore','Explore'],['customerServices','services','My Services'],['communityEvents','event','Community'],['updates','update','Updates'],['helpDesk','help','Help & Support'],['profile','profile','Profile']];
 if(state.role==='provider')return [['providerHome','dashboard','Dashboard'],['providerRequests','request','Requests'],['providerCustomers','customers','Customers'],['providerServices','services','Services'],['communityEvents','event','Community'],['updates','update','Updates'],['helpDesk','help','Help & Support'],['profile','profile','Profile']];
 if(state.role==='admin')return [['adminHome','dashboard','Desk'],['adminApplications','applications','Applications'],['adminReports','report','Reports'],['adminPeople','people','People'],['adminSettings','settings','Settings']];
 return [];
}
function shell(content,active){const items=roleNav(),current=active||state.route,collapsed=!!state.ui.navCollapsed,open=!!state.ui.navOpen;return `<main class="app-shell role-${esc(state.role||'guest')} ${collapsed?'nav-collapsed':''} ${open?'nav-open':''}"><div class="page-wrap">${content}</div>${items.length?`<button class="mobile-menu-fab" type="button" data-action="toggleNav" aria-label="Open navigation">${navIcon('menu')}</button><button class="nav-scrim" type="button" data-action="closeNav" aria-label="Close navigation"></button><nav class="side-nav" aria-label="Primary"><div class="side-brand"><span class="side-brand-mark">${navIcon('home')}</span><div><b>Neighbourly</b><small>Real people. Brighter days.</small></div></div><div class="side-nav-items">${items.map(([r,i,l])=>`<button type="button" class="nav-btn ${current===r?'active':''}" data-nav="${r}">${navIcon(i)}<b>${l}</b></button>`).join('')}</div><button class="nav-collapse" type="button" data-action="toggleNavCollapse" aria-label="${collapsed?'Expand':'Collapse'} navigation"><span>${collapsed?'›':'‹'}</span><b>${collapsed?'Expand':'Hide menu'}</b></button></nav>`:''}</main>`}
function topbar(title='Neighbourly',subtitle=''){return `<header class="topbar">${state.role?`<button type="button" class="topbar-menu" data-action="toggleNav" aria-label="Open navigation">${navIcon('menu')}</button>`:''}<div class="topbar-copy"><div class="brand-row"><span class="brand-mark">${navIcon('home')}</span><span>${esc(title)}</span></div>${subtitle?`<small>${esc(subtitle)}</small>`:''}</div><button type="button" class="icon-btn" data-action="how" aria-label="How Neighbourly works">${navIcon('help')}</button></header>`}
function communityStrip(){return `<div class="community-strip">${icon('people')}<div><b>Local help. Local opportunity. Stronger neighbourhoods.</b><small>Neighbourly is built to help people find trusted local services and help good service providers reach more neighbours.</small></div></div>`}
function connectionNote(compact=false){return `<div class="connection-note ${compact?'compact':''}"><b>Neighbourly helps you connect — the service arrangement is between customer and provider.</b><span>If something goes wrong, report it in-app. The Sisters Help Desk reviews reported platform issues fairly.</span></div>`}
function thoughtCard(){return `<div class="thought-card"><p>Good things happen when neighbours show up for each other.</p></div>`}
function sistersSupportCard(compact=false){return `<button class="sisters-support ${compact?'compact':''}" data-action="reportGeneral"><img src="sisters-help-desk.png" alt="Illustration of the Sisters Help Desk"><div><span class="support-kicker">Sisters Help Desk</span><h3>Need a hand?</h3><p>Real people. Real support.</p></div><span class="support-arrow">→</span></button>`}
function publicSistersCard(){return `<div class="public-sisters"><div class="public-sisters-image"><img src="sisters-help-desk.png" alt="Illustration of the Sisters Help Desk"></div><div><span class="support-kicker">Sisters Help Desk</span><h2>Human support, built in.</h2><p>If you ever need help, you won’t be talking to a faceless system. We’re here to help keep Neighbourly fair, clear and kind.</p><span class="hand-note">Real people. Real support.</span></div></div>`}
function homeMiniLinks(role){return role==='customer'?`<div class="home-mini-links"><button data-action="customerSafetyGuide">${icon('safety','tiny')}<span>Stay safe</span></button><button data-nav="profile">${icon('help','tiny')}<span>Help & profile</span></button></div>`:`<div class="home-mini-links"><button data-nav="providerFeatures">${icon('home','tiny')}<span>What you can do</span></button><button data-nav="updates">${icon('update','tiny')}<span>Updates</span></button></div>`}
function categoryArt(category='Other'){const c=String(category).toLowerCase();if(c.includes('clean'))return ['cleaning','services','Fresh spaces'];if(c.includes('garden'))return ['gardening','home','Green thumbs'];if(c.includes('beaut'))return ['beauty','badge','Little luxuries'];if(c.includes('food')||c.includes('cater')||c.includes('bake'))return ['food','event','Made with care'];if(c.includes('pet'))return ['pets','customers','Happy paws'];if(c.includes('hand')||c.includes('repair'))return ['handyman','settings','Handy help'];if(c.includes('tutor'))return ['tutoring','note','Learn locally'];if(c.includes('child'))return ['childcare','people','Caring hands'];if(c.includes('transport'))return ['transport','location','On the move'];return ['other','promote','Local talent']}
function serviceVisual(p){const [tone,ico,label]=categoryArt(p.category);return `<div class="service-visual tone-${tone}"><span>${icon(ico)}</span><small>${esc(label)}</small><strong>${esc(p.category||'Local service')}</strong></div>`}

function publicHome(){return shell(`<section class="public-home"><div class="public-hero-shell"><div class="hero-orb orb-one"></div><div class="hero-orb orb-two"></div><div class="hero-logo"><span>${navIcon('home')}</span><b>Neighbourly</b></div><span class="eyebrow">LOCAL SERVICES · COMMUNITY · REAL SUPPORT</span><h1>Good help should feel close to home.</h1><p>Find trusted local service providers, discover what’s happening nearby, and be part of a kinder local community.</p><div class="hero-actions"><button class="btn primary" data-nav="loginChoice">Log in</button><button class="btn soft" data-nav="joinChoice">Join Neighbourly</button></div><div class="promise-row"><span>${icon('badge','tiny')}Trust is earned</span><span>${icon('people','tiny')}Kind goes both ways</span><span>${icon('help','tiny')}Human support</span></div></div><div class="public-curated"><button class="curated-card wide" data-action="publicAbout"><span class="curated-icon">${icon('home')}</span><div><small>How it works</small><strong>Simple local connections, without the clutter.</strong></div><span>→</span></button><button class="curated-card" data-nav="publicEvents"><span class="curated-icon coral">${icon('event')}</span><div><small>Community</small><strong>See what’s happening nearby.</strong></div><span>→</span></button><button class="curated-card" data-action="publicStandards"><span class="curated-icon sage">${icon('people')}</span><div><small>The Neighbourly Way</small><strong>A kind community, with fair boundaries.</strong></div><span>→</span></button></div>${publicSistersCard()}<div class="public-footnote"><button class="text-link" data-action="publicAppeal">Appeal a Neighbourly decision</button></div>${thoughtCard()}</section>`)}
function loginChoice(){return shell(`<section class="screen narrow choice-screen">${topbar('Log in','Choose the side of Neighbourly you use.')}<div class="choice-intro"><h1>Welcome back.</h1><p>Pick your space and we’ll take you straight there.</p></div><div class="role-choice-grid"><button class="role-choice customer" data-action="chooseLogin" data-role="customer"><span class="role-choice-icon">${icon('profile')}</span><div><small>Customer</small><h2>I’m looking for a service</h2><p>Find providers, manage services and keep your favourites close.</p></div><span class="role-arrow">→</span></button><button class="role-choice provider" data-action="chooseLogin" data-role="provider"><span class="role-choice-icon">${icon('badge')}</span><div><small>Service provider</small><h2>I provide services</h2><p>Manage requests, customers, your profile and local visibility.</p></div><span class="role-arrow">→</span></button></div><button class="btn ghost" data-nav="publicHome">Back home</button></section>`)}
function joinChoice(){return shell(`<section class="screen narrow choice-screen">${topbar('Join Neighbourly','A simple start — you can add more later.')}<div class="choice-intro"><h1>Come on in.</h1><p>Neighbourly has a place for people looking for help and people offering it.</p></div><div class="role-choice-grid"><button class="role-choice customer" data-nav="joinCustomer"><span class="role-choice-icon">${icon('profile')}</span><div><small>Customer</small><h2>Find local help</h2><p>Browse, book, save favourites and stay connected to your neighbourhood.</p></div><span class="role-arrow">→</span></button><button class="role-choice provider" data-nav="joinProvider"><span class="role-choice-icon">${icon('badge')}</span><div><small>Service provider</small><h2>Offer your services</h2><p>Apply, complete Neighbourly Ready and reach local customers.</p></div><span class="role-arrow">→</span></button></div><button class="btn ghost" data-nav="publicHome">Back home</button></section>`)}
function loginForm(){const provider=state.loginRole==='provider';return shell(`<section class="screen narrow">${topbar(provider?'Service provider log in':'Customer log in',provider?'Use your email or Provider ID.':'Welcome back.')}<div class="segmented"><button type="button" class="${!provider?'active':''}" data-action="chooseLogin" data-role="customer">Customer</button><button type="button" class="${provider?'active':''}" data-action="chooseLogin" data-role="provider">Service provider</button></div><div class="card" style="margin-top:12px"><form id="loginForm" class="form" novalidate><div class="field"><label>${provider?'Email or Provider ID':'Email'}<input name="identifier" autocomplete="username" required placeholder="${provider?'you@example.com or N7R2DY':'you@example.com'}"></label></div><div class="field"><label>Password<input name="password" type="password" autocomplete="current-password" required></label></div><div class="form-error" id="loginError"></div><button class="btn primary" type="submit">Log in</button></form></div><div class="soft-note">Prototype test accounts use a demo password. Real launch authentication will use secure server-side accounts.</div><button class="btn ghost" data-nav="loginChoice">Back</button></section>`)}
function baseSignup(role){const provider=role==='provider';return shell(`<section class="screen narrow">${topbar(provider?'Join as a service provider':'Create your customer account',provider?'Your application and Neighbourly Ready come next.':'A quick hello, then you’re in.')}<div class="card"><form id="signupForm" class="form" data-role="${role}" novalidate><div class="field two"><label>First name<input name="first" required maxlength="35"></label><label>Surname<input name="last" required maxlength="35"></label></div><div class="field"><label>Email<input name="email" type="email" required></label></div><div class="field"><label>Mobile number<input name="phone" inputmode="tel" required placeholder="e.g. 072 123 4567"></label></div><div class="field"><label>Neighbourhood<input name="area" required maxlength="50" placeholder="e.g. Westridge"></label></div><div class="field"><label>Password<input name="password" type="password" minlength="8" required><small>Use something you don’t use elsewhere.</small></label></div><label class="check"><input name="community" type="checkbox" required><span>I agree to help keep Neighbourly respectful and kind. Abuse, threats, harassment, discrimination, scams and deliberate exploitation are not accepted.</span></label><div class="form-error" id="signupError"></div><button class="btn primary" type="submit">${provider?'Create provider account':'Create my account'}</button></form></div><button class="btn ghost" data-nav="joinChoice">Back</button></section>`)}

function approvedProviders(){return state.providers.filter(p=>p.status==='approved'&&!p.hideFromSearch)}

function activePromotionsFor(providerId){const now=Date.now();return (state.promotions||[]).filter(x=>x.providerId===providerId&&(!x.expiresAt||x.expiresAt>now))}
function isProviderPromoted(p,area='All'){return activePromotionsFor(p.providerId).some(x=>area==='All'||x.area===area)}

function providerCard(p){const a=currentAccount();const promoted=isProviderPromoted(p,state.ui.area||'All');const fav=!!a&&state.favourites.providers.some(x=>x.customerId===a.id&&x.providerId===p.providerId),photo=(p.gallery||[])[0];return `<article class="card provider-card">${photo?`<img class="provider-work-thumb" src="${photo.dataUrl}" alt="Example of ${esc(p.service)}">`:serviceVisual(p)}<div class="provider-top"><div class="avatar lg">${initials(p.name)}</div><div class="grow"><div class="name-line"><h3>${esc(p.name)}</h3>${p.identityVerified?'<span class="verified">✓ Identity confirmed</span>':''}${promoted?'<span class="promoted">PROMOTED</span>':''}</div><p>${esc(p.category)} · ${esc(p.area)}</p></div><button type="button" class="heart ${fav?'on':''}" data-action="toggleProviderFav" data-id="${esc(p.providerId)}">${fav?'♥':'♡'}</button></div><div class="badge-row">${(p.badges||[]).slice(0,3).map(b=>`<span class="trust-badge">${esc(b)}</span>`).join('')}</div><div class="service-title">${esc(p.service)}</div><p class="muted">${esc(p.about)}</p><div class="provider-meta"><span>★ ${esc(p.rating)} <small>(${esc(p.reviews)})</small></span><span>${moneySafe(p.price)}</span><span>${esc(p.availability)}</span></div>${p.paused?`<div class="away-banner"><b>Taking a breather</b><small>${p.awayMessage?esc(p.awayMessage):(p.pauseReturn?`Back from ${dateText(p.pauseReturn)}.`:'Not accepting new requests right now.')} You can still save this provider for later.</small></div>`:''}<div class="card-actions"><button class="btn secondary small" data-action="viewProvider" data-id="${esc(p.providerId)}">View profile</button><button class="btn primary small" data-action="requestService" data-id="${esc(p.providerId)}" ${p.paused?'disabled':''}>Request service</button></div></article>`}

function providerMiniCard(p){
  const a=currentAccount(),promoted=isProviderPromoted(p,state.ui.area||'All'),fav=!!a&&state.favourites.providers.some(x=>x.customerId===a.id&&x.providerId===p.providerId),photo=(p.gallery||[])[0];
  return `<article class="provider-mini-card"><button type="button" class="provider-mini-main" data-action="viewProvider" data-id="${esc(p.providerId)}">${photo?`<img class="provider-mini-image" src="${photo.dataUrl}" alt="Example of ${esc(p.service)}">`:serviceVisual(p)}<div class="provider-mini-copy"><div class="provider-mini-name"><b>${esc(p.name)}</b>${p.identityVerified?'<span class="verified mini">✓</span>':''}${promoted?'<span class="promoted">Promoted</span>':''}</div><span>${esc(p.service)}</span><small>★ ${esc(p.rating)} (${esc(p.reviews)}) · ${moneySafe(p.price)}</small></div></button><button type="button" class="heart provider-mini-heart ${fav?'on':''}" data-action="toggleProviderFav" data-id="${esc(p.providerId)}" aria-label="${fav?'Remove from':'Add to'} favourites">${fav?'♥':'♡'}</button></article>`
}
function homeQuick(role){const customer=role==='customer';return `<div class="home-bento">${customer?`<button class="bento-card coral" data-nav="customerServices">${icon('services')}<div><b>My Services</b><small>Requests, bookings and completed work.</small></div></button><button class="bento-card sage" data-nav="customerFavourites">${icon('badge')}<div><b>Favourites</b><small>Your go-to providers, ready for next time.</small></div></button><button class="bento-card sun" data-nav="communityEvents">${icon('event')}<div><b>Community events</b><small>What’s happening around you.</small></div></button><button class="bento-card teal" data-nav="updates">${icon('update')}<div><b>Updates</b><small>Important notes and good news.</small></div></button>`:`<button class="bento-card coral" data-nav="providerRequests">${icon('request')}<div><b>Requests</b><small>See who needs your help.</small></div></button><button class="bento-card sage" data-nav="providerCustomers">${icon('customers')}<div><b>Customers</b><small>History, favourites and private notes.</small></div></button><button class="bento-card sun" data-nav="communityEvents">${icon('event')}<div><b>Community events</b><small>See what’s happening nearby.</small></div></button><button class="bento-card teal" data-nav="providerGrowth">${icon('promote')}<div><b>Reach more neighbours</b><small>Badges, Boosts and visibility.</small></div></button>`}</div>`}
function customerHome(){const a=currentAccount();const fav=approvedProviders().filter(p=>state.favourites.providers.some(x=>x.customerId===a?.id&&x.providerId===p.providerId)).slice(0,3),featured=fav.length?fav:approvedProviders().slice(0,3);return shell(`<section class="screen home-screen">${topbar('Neighbourly',`${a?.area||'Your neighbourhood'} · nice to see you`)}${a?.accountStatus==='restricted'?`<div class="danger-note"><b>Account temporarily restricted</b><span>You can still browse and contact the Sisters Help Desk, but new service requests are paused until ${a.restrictionUntil?dateText(a.restrictionUntil):'the restriction is reviewed'}.</span></div>`:''}<div class="home-hero customer-home-hero"><span class="home-kicker">Hi, ${esc(a?.first||'Neighbour')}.</span><h1>What can we help with today?</h1><button class="home-search" data-nav="findHelp">${icon('search')}<span><b>Find help nearby</b><small>Search services, providers or areas</small></span><strong>→</strong></button></div>${homeQuick('customer')}${homeMiniLinks('customer')}<section class="home-section"><div class="section-title compact"><div><span class="section-kicker">For you</span><h2>${fav.length?'Your go-to providers':'Good people nearby'}</h2></div><button data-nav="findHelp">Explore all</button></div><div class="home-provider-rail">${featured.map(providerMiniCard).join('')}</div></section>${spotlightBlock()}<div class="home-support-grid">${updatesPreview()}${sistersSupportCard(true)}</div>${thoughtCard()}</section>`,'customerHome')}
function spotlightBlock(){const list=approvedProviders().filter(p=>isProviderPromoted(p)).slice(0,2);return list.length?`<section class="home-section spotlight-section"><div class="section-title compact"><div><span class="section-kicker">Paid visibility</span><h2>Neighbourly Spotlight</h2></div><span class="mini-pill">Promoted</span></div><div class="home-provider-rail">${list.map(providerMiniCard).join('')}</div><p class="section-note">Promotions are clearly marked. Trust badges still have to be earned.</p></section>`:''}
function updatesPreview(){const latest=[...(state.updates||[])].sort((a,b)=>b.createdAt-a.createdAt)[0];return latest?`<button class="update-preview ${esc(latest.type)}" data-nav="updates"><span class="update-dot"></span><div><small>Neighbourly update · ${dateText(latest.createdAt)}</small><h3>${esc(latest.title)}</h3><p>${esc(latest.body)}</p></div><strong>→</strong></button>`:''}
function findHelp(){const cats=['All',...new Set(approvedProviders().map(p=>p.category))],areas=['All',...new Set(approvedProviders().flatMap(p=>p.areas||[p.area]))];return shell(`<section class="screen">${topbar('Explore','Find local help that fits.')}<div class="filter-card"><div class="field"><label>What do you need?<input id="providerSearch" value="${esc(state.ui.search)}" placeholder="Try cleaning, baking or a provider name"></label></div><div class="filter-row"><select id="categoryFilter">${cats.map(c=>`<option ${state.ui.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="areaFilter">${areas.map(c=>`<option ${state.ui.area===c?'selected':''}>${esc(c)}</option>`).join('')}</select>${state.role==='customer'?`<button class="btn secondary" data-action="customerSafetyGuide">Stay safe with Neighbourly</button>`:''}<button class="btn secondary" data-nav="communityEvents">Community events</button></div></div><div class="section-title"><h2>Local service providers</h2><span id="resultCount" class="count-pill"></span></div><div id="providerResults" class="grid-cards"></div></section>`,'findHelp')}
function renderFindResults(){const q=(state.ui.search||'').toLowerCase().trim();const list=approvedProviders().filter(p=>{const mq=!q||[p.name,p.category,p.service,p.about,p.area,...(p.areas||[])].join(' ').toLowerCase().includes(q),mc=state.ui.category==='All'||p.category===state.ui.category,ma=state.ui.area==='All'||(p.areas||[p.area]).includes(state.ui.area);return mq&&mc&&ma}).sort((a,b)=>Number(isProviderPromoted(b,state.ui.area))-Number(isProviderPromoted(a,state.ui.area)));if($('#providerResults'))$('#providerResults').innerHTML=list.length?list.map(providerCard).join(''):`<div class="card empty"><h3>No exact matches</h3><p>Try another category or nearby area.</p></div>`;if($('#resultCount'))$('#resultCount').textContent=`${list.length} found`;bindDynamic()}
function customerFavourites(){const a=currentAccount(),list=approvedProviders().filter(p=>state.favourites.providers.some(x=>x.customerId===a?.id&&x.providerId===p.providerId));return shell(`<section class="screen">${topbar('Favourites','Your go-to providers.')}<div class="grid-cards">${list.length?list.map(providerCard).join(''):`<div class="card empty"><div class="big">♡</div><h3>No favourites yet</h3><p>When you find someone great, save them here for next time.</p><button class="btn primary" data-nav="findHelp">Explore providers</button></div>`}</div></section>`,'customerFavourites')}
function statusPill(s){const label={awaiting:'Pending',accepted:'Accepted',in_progress:'In progress',completed:'Completed',cancelled:'Cancelled',declined:'Declined',ready_for_review:'Ready for review',changes:'Changes needed',approved:'Approved',restricted:'Restricted'}[s]||titleCase(s||'pending');return `<span class="status status-${esc(s||'awaiting')}">${esc(label)}</span>`}
function extraWorkBlock(r,viewer){const e=r.extraWork;if(!e)return'';let label={customer_requested:'Waiting for provider',provider_proposed:'Waiting for customer',confirmed:'Extra work approved',declined:'Extra work declined'}[e.status]||e.status;return `<div class="extra-card"><b>Extra work · ${esc(label)}</b><small>${esc(e.description||'')}</small>${e.addedCost?`<small>Extra cost: R${esc(e.addedCost)}</small>`:''}${viewer==='customer'&&e.status==='provider_proposed'?`<div class="card-actions"><button class="btn primary small" data-action="confirmExtra" data-id="${r.id}">Confirm change</button><button class="btn secondary small" data-action="declineExtraCustomer" data-id="${r.id}">Decline</button></div>`:''}${viewer==='provider'&&e.status==='customer_requested'?`<div class="card-actions"><button class="btn primary small" data-action="reviewExtra" data-id="${r.id}">Review request</button><button class="btn secondary small" data-action="declineExtraProvider" data-id="${r.id}">Decline</button></div>`:''}</div>`}
function customerServices(){const a=currentAccount(),list=state.requests.filter(r=>r.customerId===a?.id).sort((x,y)=>y.createdAt-x.createdAt);return shell(`<section class="screen">${topbar('My Services','Requests, bookings and completed work.')}<div class="stack">${list.length?list.map(r=>{const p=state.providers.find(x=>x.providerId===r.providerId);return `<article class="card request-card"><div class="request-head"><div><h3>${esc(r.service)}</h3><p>${esc(p?.name||r.providerName)}</p></div>${statusPill(r.status)}</div><div class="request-details"><span>${dateText(r.date||r.createdAt)}</span><span>${esc(a?.area||'')}</span>${r.serviceCode&&['accepted','in_progress'].includes(r.status)?`<span>Service Code: <b>${r.serviceCode}</b></span>`:''}</div>${r.note?`<p class="muted">${esc(r.note)}</p>`:''}${messageThread(r)}${extraWorkBlock(r,'customer')}${safetyStatusBanner(r)}<div class="card-actions">${r.status==='awaiting'?`<button class="btn secondary small" data-action="messageRequest" data-id="${r.id}">Message provider</button><button class="btn secondary small" data-action="cancelRequest" data-id="${r.id}">Cancel request</button>`:''}${['accepted','in_progress'].includes(r.status)&&(!r.extraWork||['confirmed','declined'].includes(r.extraWork.status))?`<button class="btn secondary small" data-action="addExtraWork" data-id="${r.id}">Add extra work</button>`:''}${['accepted','in_progress'].includes(r.status)?`<button class="btn secondary small" data-action="messageRequest" data-id="${r.id}">Messages</button><button class="btn primary small" data-action="customerCheckin" data-id="${r.id}">Safety tools</button>`:''}${r.status==='accepted'?`<button class="btn ghost small" data-action="cancelBooking" data-id="${r.id}">Cancel booking</button>`:''}${r.providerMarkedDone&&['accepted','in_progress'].includes(r.status)?`<button class="btn primary small" data-action="confirmComplete" data-id="${r.id}">Confirm completed</button>`:''}${r.status==='completed'&&!r.customerRating?`<button class="btn primary small" data-action="rateProvider" data-id="${r.id}">How did it go?</button>`:''}${r.customerRating?`<span class="rating-done">★ ${r.customerRating} · Thanks for reviewing</span>`:''}${r.status==='completed'?`<button class="btn secondary small" data-action="bookAgain" data-id="${r.id}">Book again</button>`:''}</div></article>`}).join(''):`<div class="card empty"><h3>Nothing here yet</h3><p>Your service requests will appear here.</p><button class="btn primary" data-nav="findHelp">Find help nearby</button></div>`}</div></section>`,'customerServices')}

function providerHow(){const p=currentProvider();return shell(`<section class="screen narrow">${topbar('Start with Neighbourly','A simple path from local skill to local work.')}<div class="steps"><div><b>1</b><span><strong>Build your application</strong><small>Tell us what you do, where you work and how you learned your skill.</small></span></div><div><b>2</b><span><strong>Complete Neighbourly Ready</strong><small>Short, practical training with simple checks and no timer.</small></span></div><div><b>3</b><span><strong>Sisters Help Desk review</strong><small>We verify identity, experience or qualifications, and any category-specific requirements.</small></span></div><div><b>4</b><span><strong>Go live</strong><small>Only approved providers can appear publicly.</small></span></div></div><div class="provider-id-card"><small>Your Provider ID</small><strong>${esc(p?.providerId||'')}</strong><span>Keep this somewhere safe — it can be used instead of your email to log in.</span></div>${communityStrip()}<button class="btn secondary" data-nav="providerFeatures">See what you can do on Neighbourly</button><button class="btn primary" data-nav="providerApplication">Start my application</button></section>`)}
function providerApplication(){const p=currentProvider();if(!p)return providerHow();if(['submitted','ready_for_review','approved'].includes(p.applicationStatus))return providerHome();return shell(`<section class="screen narrow">${topbar('Provider application','Clear, simple and reviewed by people.')}<div class="progress"><span class="on"></span><span></span><span></span><span></span><span></span></div><form id="providerApplicationForm" class="card form" novalidate><div class="field"><label>Main service category<select name="category" required><option value="">Choose one</option>${['Cleaning','Handyman','Beauty','Gardening','Food','Transport','Tutoring','Childcare','Pet care','Other'].map(x=>`<option ${p.category===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="field"><label>Service name<input name="service" maxlength="70" required value="${esc(p.service||'')}"></label></div><div class="field"><label>Tell neighbours what you do<textarea name="about" maxlength="350" required>${esc(p.about||'')}</textarea></label></div><div class="field"><label>Starting price<input name="price" maxlength="35" value="${esc(p.price||'')}"></label></div><div class="field"><label>Areas you serve<input name="areas" maxlength="160" required value="${esc((p.areas||[]).join(', '))}"></label></div><div class="field"><label>Availability<input name="availability" maxlength="80" required value="${esc(p.availability||'')}"></label></div><div class="field"><label>Your experience<textarea name="experience" maxlength="350" required>${esc(p.experience||'')}</textarea></label></div><div class="field"><label>How should we verify your background?<select name="credentialPath" required><option value="">Choose one</option><option value="experienced" ${p.credentialPath==='experienced'?'selected':''}>Experienced with no formal qualification</option><option value="qualified" ${p.credentialPath==='qualified'?'selected':''}>Experienced with a relevant qualification</option><option value="registered" ${p.credentialPath==='registered'?'selected':''}>Registered professional / trade where applicable</option></select></label></div><label class="check"><input name="agree" type="checkbox" required><span>I understand that I must complete Neighbourly Ready and pass verification before my profile can go live.</span></label><div class="form-error" id="applicationError"></div><button class="btn primary" type="submit">Save application & continue</button></form></section>`)}
function applicationTimeline(p){const steps=[['Application submitted',!!p.applicationStatus],['Neighbourly Ready passed',!!p.onboardingPassed],['Sisters Help Desk review',['ready_for_review','approved','changes'].includes(p.applicationStatus)],['Verification complete',!!(p.identityVerified&&p.credentialVerified&&p.categoryVerified&&(!p.siteVisitRequired||p.siteVisitDone))],['Final decision',p.status==='approved']];return `<div class="timeline">${steps.map(([t,on])=>`<div class="timeline-item ${on?'done':''}"><span class="timeline-dot"></span><div><b>${t}</b><small>${on?'Complete':'Waiting'}</small></div></div>`).join('')}</div>${(p.applicationUpdates||[]).length?`<div class="section-title"><h2>Application updates</h2></div><div class="stack">${[...p.applicationUpdates].sort((a,b)=>b.t-a.t).map(u=>`<div class="card update-card info"><span class="update-dot"></span><div><h3>${esc(u.text)}</h3><small>${dateText(u.t)}</small></div></div>`).join('')}</div>`:''}`}
function onboardingChecklist(p){return `<div class="checklist"><div class="done"><span>✓</span>Account created</div><div class="${p.applicationStatus?'done':''}"><span>${p.applicationStatus?'✓':'○'}</span>Application submitted</div><div class="${p.onboardingPassed?'done':''}"><span>${p.onboardingPassed?'✓':'○'}</span>Neighbourly Ready</div><div class="${p.applicationStatus==='ready_for_review'||p.status==='approved'?'done':''}"><span>${p.applicationStatus==='ready_for_review'||p.status==='approved'?'✓':'○'}</span>Sisters Help Desk review</div><div class="${p.status==='approved'?'done':''}"><span>${p.status==='approved'?'✓':'○'}</span>Profile live</div></div>`}
function providerHome(){const p=currentProvider(),a=currentAccount();if(!p)return publicHome();if(!p.applicationStatus)return providerHow();if(p.status==='restricted')return shell(`<section class="screen home-screen">${topbar('Provider Dashboard',`${p.providerId} · ${a?.area||''}`)}<div class="danger-note"><b>Account temporarily restricted</b><span>Your public profile and new service activity are paused until ${p.restrictionUntil?dateText(p.restrictionUntil):'the Sisters Help Desk completes the restriction period'}. You can still view your account and contact support.</span></div>${homeQuick('provider')}${sistersSupportCard(true)}</section>`,'providerHome');const mine=state.requests.filter(r=>r.providerId===p.providerId),awaiting=mine.filter(r=>r.status==='awaiting').length,booked=mine.filter(r=>['accepted','in_progress'].includes(r.status)).length;if(p.status!=='approved')return shell(`<section class="screen home-screen">${topbar('Provider Dashboard',`${p.providerId} · ${a?.area||''}`)}<div class="home-hero provider-home-hero"><span class="home-kicker">${p.onboardingPassed?'Neighbourly Ready ✓':'Your application'}</span><h1>${p.onboardingPassed?'You’ve done your part.':'You’re making progress.'}</h1><p>${p.onboardingPassed?'Your application can now be reviewed and verified by the Sisters Help Desk.':'Complete Neighbourly Ready before your application moves to review.'}</p><div class="hero-actions inline">${!p.onboardingPassed?`<button class="btn primary" data-nav="providerReady">Continue Neighbourly Ready</button>`:''}<button class="btn soft" data-nav="providerFeatures">See app features</button></div></div><div class="progress-panel"><div class="section-title compact"><div><span class="section-kicker">Application</span><h2>Where you are</h2></div></div>${onboardingChecklist(p)}</div><details class="application-drawer"><summary>Application updates <span>→</span></summary><div>${applicationTimeline(p)}</div></details>${homeQuick('provider')}${homeMiniLinks('provider')}${sistersSupportCard(true)}${thoughtCard()}</section>`,'providerHome');return shell(`<section class="screen home-screen">${topbar('Provider Dashboard',`${p.providerId} · ${a?.area||''}`)}<div class="home-hero provider-home-hero"><span class="home-kicker">${p.paused?'Taking a breather':'Your corner of the neighbourhood'}</span><h1>Hi, ${esc(a?.first||'Neighbour')}.</h1><p>${p.paused?'Your profile is paused for new requests.':'Here’s what needs your attention today.'}</p></div>${membershipBreakNotice(p)}<div class="metric-strip"><button data-nav="providerRequests"><b>${awaiting}</b><span>New requests</span></button><button data-nav="providerRequests"><b>${booked}</b><span>Booked</span></button><button data-nav="providerGrowth"><b>${p.boosts||0}</b><span>Boosts</span></button></div>${homeQuick('provider')}${homeMiniLinks('provider')}<section class="home-section"><div class="section-title compact"><div><span class="section-kicker">Next up</span><h2>Your active services</h2></div><button data-nav="providerRequests">See all</button></div><div class="compact-stack">${mine.filter(r=>['awaiting','accepted','in_progress'].includes(r.status)).slice(0,2).map(providerRequestCard).join('')||`<div class="quiet-empty"><span>${icon('checkin')}</span><div><b>Nothing urgent right now.</b><small>Your profile is ready for neighbours to find.</small></div></div>`}</div></section><div class="home-support-grid">${updatesPreview()}${sistersSupportCard(true)}</div>${thoughtCard()}</section>`,'providerHome')}
function providerRequestCard(r){const c=state.accounts.find(a=>a.id===r.customerId);return `<article class="card request-card"><div class="request-head"><div><h3>${esc(r.service)}</h3><p>${esc(c?`${c.first} ${c.last}`:r.customerName)} · ${esc(c?.area||'')}</p></div>${statusPill(r.status)}</div><div class="request-details"><span>${dateText(r.date||r.createdAt)}</span>${r.serviceCode&&['accepted','in_progress'].includes(r.status)?`<span>Service Code: <b>${r.serviceCode}</b></span>`:''}</div>${r.note?`<p class="muted">${esc(r.note)}</p>`:''}${messageThread(r)}${extraWorkBlock(r,'provider')}${safetyStatusBanner(r)}<div class="card-actions">${r.status==='awaiting'?`<button class="btn primary small" data-action="acceptRequest" data-id="${r.id}">Accept request</button><button class="btn secondary small" data-action="messageRequest" data-id="${r.id}">Ask a question</button><button class="btn secondary small" data-action="declineRequest" data-id="${r.id}">Decline</button>`:''}${['accepted','in_progress'].includes(r.status)?`<button class="btn secondary small" data-action="messageRequest" data-id="${r.id}">Messages</button><button class="btn secondary small" data-action="providerSafety" data-id="${r.id}">Safety tools</button><button class="btn primary small" data-action="providerComplete" data-id="${r.id}">Mark done</button>${r.status==='accepted'?`<button class=\"btn ghost small\" data-action=\"cancelBooking\" data-id=\"${r.id}\">Cancel booking</button>`:''}`:''}</div></article>`}
function providerRequests(){const p=currentProvider(),list=state.requests.filter(r=>r.providerId===p?.providerId).sort((a,b)=>b.createdAt-a.createdAt);return shell(`<section class="screen">${topbar('Requests','Read first. Ask if you’re unsure. Accept carefully.')}<div class="stack">${list.length?list.map(providerRequestCard).join(''):`<div class="card empty"><h3>No requests yet</h3><p>When a customer requests your service, it’ll appear here.</p></div>`}</div></section>`,'providerRequests')}
function providerCustomers(){const p=currentProvider(),ids=[...new Set(state.requests.filter(r=>r.providerId===p?.providerId).map(r=>r.customerId))];return shell(`<section class="screen">${topbar('Customers','Useful private memory, just for you.')}<div class="privacy-banner"><b>Private to you</b><span>Favourite customers, work-again ratings and notes are never shown to customers or other providers.</span></div><div class="stack">${ids.length?ids.map(id=>{const c=state.accounts.find(a=>a.id===id);if(!c)return'';const key=`${p.providerId}:${id}`,note=state.customerNotes[key]||{},fav=state.favourites.customers.some(x=>x.providerId===p.providerId&&x.customerId===id);return `<article class="card customer-card"><div class="provider-top"><div class="avatar">${initials(`${c.first} ${c.last}`)}</div><div class="grow"><h3>${esc(c.first+' '+c.last)}</h3><p>${esc(c.area)} · ${c.identityVerified?'Identity confirmed':'Identity not yet confirmed'}</p></div><button class="heart ${fav?'on':''}" data-action="toggleCustomerFav" data-id="${id}">${fav?'♥':'♡'}</button></div><div class="customer-memory"><span>Would work again: ${note.rating?`★ ${note.rating}/5`:'Not rated yet'}</span>${note.note?`<p>${esc(note.note)}</p>`:''}</div><button class="btn secondary small" data-action="customerNote" data-id="${id}">${note.note||note.rating?'Edit private note':'Add private note'}</button></article>`}).join(''):`<div class="card empty"><h3>Your customer list is empty</h3><p>After customers request your service, you can keep useful private notes here.</p></div>`}</div></section>`,'providerCustomers')}
function providerServices(){const p=currentProvider(),gallery=p?.gallery||[];return shell(`<section class="screen">${topbar('Services','What neighbours see when they find you.')}<article class="card"><div class="provider-top"><div class="avatar lg">${initials(p?.name||'Provider')}</div><div class="grow"><h2>${esc(p?.name||'Your profile')}</h2><p>${esc(p?.category||'')}</p></div></div><h3>${esc(p?.service||'')}</h3><p class="muted">${esc(p?.about||'')}</p><div class="provider-meta"><span>${moneySafe(p?.price)}</span><span>${esc(p?.availability||'')}</span></div><div class="badge-row">${(p?.badges||[]).map(b=>`<span class="trust-badge">${esc(b)}</span>`).join('')}</div></article>${membershipBreakNotice(p)}<div class="card" style="margin-top:14px"><div class="provider-top">${icon('pause')}<div class="grow"><h3>Pause availability</h3><p>${p?.paused&&!p?.membershipBreakUntil?'Taking a breather — not accepting new requests right now.':'Need some time away? Pause new requests for a while.'}</p></div></div><button class="btn ${p?.paused&&!p?.membershipBreakUntil?'secondary':'primary'}" data-action="pauseProvider">${p?.paused&&!p?.membershipBreakUntil?'Back in the neighbourhood':'Pause availability'}</button></div><div class="card" style="margin-top:14px"><h3>Your membership</h3><p class="muted">${esc(p?.membership||'Start')} · ${p?.boosts||0} Boosts available</p><button class="btn secondary" data-nav="providerGrowth">Reach more neighbours</button><button class="btn ghost" data-action="membershipBreak">${p?.membershipBreakUntil?'End membership break early':'Take a membership break'}</button></div><div class="card" style="margin-top:14px"><div class="provider-top">${icon('services')}<div class="grow"><h3>Work gallery</h3><p>Show genuine examples of your work. Customer details should never appear without permission.</p></div><span class="count-pill">${gallery.length}/3</span></div>${gallery.length?`<div class="work-gallery">${gallery.map(x=>`<figure><img src="${x.dataUrl}" alt="Provider work example"><figcaption>${esc(x.caption||'Work example')}</figcaption><button class="btn ghost small" data-action="deletePortfolioPhoto" data-id="${x.id}">Remove</button></figure>`).join('')}</div>`:`<div class="soft-note">No work photos yet. Add a few clear examples that help customers understand your work.</div>`}<div class="card-actions"><button class="btn primary small" data-action="addPortfolioPhoto" ${gallery.length>=3?'disabled':''}>Add work photo</button><button class="btn secondary small" data-action="portfolioInfo">Photo rules</button></div></div></section>`,'providerServices')}

function providerFeatures(){const groups=[['Everyday work',[['profile','Your Provider Profile','Show customers your services, experience, prices, areas, availability, badges and reviews.'],['request','Service Requests','See who needs your help. Accept, ask a question or decline.'],['services','Your Services','Keep what you offer, pricing and service areas up to date.'],['extra','Extra Work','A customer can request extra work. Nothing changes until both sides agree.'],['customers','Customers','Keep useful service history, favourites and private notes together.']]],['Your reputation & reach',[['badge','Your Badges','See the trust badges you have genuinely earned or had verified.'],['promote','Reach more neighbours','Use Boosts and promotions to get more local visibility.'],['insights','Your Visibility','See useful performance information available with your membership.'],['membership','Your Membership','Choose the business package that fits you. Essential safety and support are not luxury features.']]],['Time away, safety & support',[['pause','Pause availability','Take a breather without losing your profile or history.'],['safety','Safety','Use Service Codes, check-ins, sharing and reporting tools.'],['help','Sisters Help Desk','Real people. Real support. Ask us when you need a hand.']]]];return shell(`<section class="screen narrow feature-screen">${topbar('What you can do on Neighbourly','A quick tour — this is not part of your test.')}<div class="feature-intro"><span class="section-kicker">Quick tour</span><h1>Everything has a place.</h1><p>You don’t need to remember it all. Open a section when you want to see what’s available.</p></div><div class="feature-groups">${groups.map((g,gi)=>`<details class="feature-group" ${gi===0?'open':''}><summary><span>${g[0]}</span><small>${g[1].length} features</small><b>+</b></summary><div class="feature-mini-grid">${g[1].map(([i,t,b])=>`<div class="feature-mini">${icon(i)}<div><h3>${esc(t)}</h3><p>${esc(b)}</p>${lookFor(i,t)}</div></div>`).join('')}</div></details>`).join('')}</div><div class="sticky-actions"><button class="btn primary" data-nav="providerReady">Start Neighbourly Ready</button><a class="btn soft link-btn" href="neighbourly-quick-start-guide.pdf" target="_blank" rel="noopener">Download Quick Start Guide</a></div></section>`)}
function trainingState(){const p=currentProvider();if(!p)return null;return state.training[p.providerId]||(state.training[p.providerId]={section:0,screen:0,sectionPassed:{},finalAnswers:{},finalPassed:false})}
function providerReady(){const p=currentProvider(),t=trainingState();if(!p)return providerHome();if(t.finalPassed)return readyCompleteScreen(p);const sec=trainingSections[t.section||0];return shell(`<section class="screen narrow">${topbar('Neighbourly Ready','Short, useful and easy to remember.')}<div class="training-head"><span class="training-progress">Section ${(t.section||0)+1} of ${trainingSections.length}</span><span class="mini-pill">No timer</span></div><div class="card lesson-card"><div class="provider-top">${icon(sec.icon)}<div><h1>${esc(sec.title)}</h1><p>${esc(sec.screens[t.screen||0][0])}</p></div></div><p>${esc(sec.screens[t.screen||0][1])}</p>${relevantLookFor(sec.id)}${t.screen===sec.screens.length-1?`<div class="remember"><b>Remember</b><span>${esc(sec.remember)}</span></div>`:''}<div class="training-nav"><button class="btn secondary" data-action="trainingBack" ${t.section===0&&t.screen===0?'disabled':''}>Back</button><button class="btn primary" data-action="trainingNext">${t.screen===sec.screens.length-1?'Quick Check':'Next'}</button></div></div><div class="soft-note">Your progress saves automatically. You can come back anytime.</div></section>`)}
function relevantLookFor(id){const map={profile:['profile','Profile'],requests:['request','Requests'],customers:['extra','Extra Work'],finish:['note','Private notes'],safety:['report','Report a problem'],works:['help','Sisters Help Desk'],way:['people','Community Standard']};const x=map[id];return x?lookFor(x[0],x[1]):''}
function sectionQuiz(){const t=trainingState(),sec=trainingSections[t.section],answers=t.sectionAnswers||{};return shell(`<section class="screen narrow">${topbar(`${sec.title} · Quick Check`,'A few short questions from this section.')}<form id="sectionQuizForm" class="card form">${sec.questions.map((q,i)=>`<fieldset style="border:0;padding:0;margin:0 0 16px"><legend style="font-weight:900;margin-bottom:7px">${i+1}. ${esc(q[0])}</legend>${q[1].map((o,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}" ${answers[i]===j?'checked':''}><span>${esc(o)}</span></label>`).join('')}</fieldset>`).join('')}<div class="form-error" id="quizError"></div><button class="btn primary" type="submit">Check my answers</button><button class="btn ghost" type="button" data-nav="providerReady">Back to section</button></form></section>`)}
function sectionResult(score,total,passed){const t=trainingState(),sec=trainingSections[t.section];return shell(`<section class="screen narrow">${topbar(sec.title,'Quick Check result')}<div class="card quiz-score"><strong>${score}/${total}</strong><h2>${passed?'Nice work ✓':'Nearly there'}</h2><p class="muted">${passed?'You’ve got the important parts of this section.':'Have another look and try again. There’s no timer and no penalty for retrying.'}</p>${passed?`<button class="btn primary" data-action="nextTrainingSection">${t.section===trainingSections.length-1?'Go to final Ready Check':'Next section'}</button>`:`<button class="btn primary" data-action="retrySection">Review this section</button>`}</div></section>`)}
function finalReadyIntro(){const p=currentProvider(),t=trainingState(),m=categoryModuleFor(p);if(m&&!t.categoryPassed?.[p.category])return categoryReady();return shell(`<section class="screen narrow">${topbar('Neighbourly Ready Check','One last quick recap before you’re done.')}<div class="card"><h1>15 everyday situations</h1><p class="muted">There is no timer, no trick wording and unlimited retries. You need 12 out of 15 overall, and every important safety/integrity question must be correct.</p><div class="privacy-banner"><b>We want you to succeed</b><span>If something trips you up, Neighbourly will show you what to revisit.</span></div><button class="btn primary" data-nav="finalReadyQuiz">I’m ready</button></div></section>`)}
function finalReadyQuiz(){const p=currentProvider(),t=trainingState(),m=categoryModuleFor(p);if(m&&!t.categoryPassed?.[p.category])return categoryReady();return shell(`<section class="screen narrow">${topbar('Neighbourly Ready Check','Take your time.')}<form id="finalReadyForm" class="card form">${finalQuestions.map((q,i)=>`<fieldset style="border:0;padding:0;margin:0 0 18px"><legend style="font-weight:900;margin-bottom:7px">${i+1}. ${esc(q[0])}${q[3]?` <span class="mini-pill">Important</span>`:''}</legend>${q[1].map((o,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}" ${Number(t.finalAnswers?.[i])===j?'checked':''}><span>${esc(o)}</span></label>`).join('')}</fieldset>`).join('')}<div class="form-error" id="finalQuizError"></div><button class="btn primary" type="submit">Check my Ready result</button></form></section>`)}
function finalReadyResult(score,criticalOk,passed){return shell(`<section class="screen narrow">${topbar('Neighbourly Ready Check','Result')}<div class="card quiz-score"><strong>${score}/15</strong><h2>${passed?'You’re Neighbourly Ready! ':'Nearly there'}</h2><p class="muted">${passed?'You’ve completed your provider onboarding. Your application can now move to the Sisters Help Desk for review and verification.':criticalOk?'You need 12 out of 15 to pass.':'One or more important safety/integrity questions needs another look.'}</p>${passed?`<button class="btn primary" data-action="finishReady">View my application</button>`:`<button class="btn primary" data-action="retryFinal">Try the Ready Check again</button><button class="btn secondary" data-nav="providerReady">Review training</button>`}</div></section>`)}
function readyCompleteScreen(p){return shell(`<section class="screen narrow">${topbar('You’re Neighbourly Ready!','Nice work.')}<div class="card quiz-score"><strong>✓</strong><h2>Training complete</h2><p class="muted">Your application is ready for the Sisters Help Desk to review and verify. Passing training does not automatically mean approval.</p><button class="btn primary" data-nav="providerHome">View my application</button></div></section>`)}

function providerGrowth(){const p=currentProvider();return shell(`<section class="screen growth-screen">${topbar('Reach more neighbours','Visibility, promotions and earned trust.')}<div class="growth-hero"><span class="section-kicker">Your reputation stays yours</span><h1>Trust is earned. Reach can be purchased.</h1><p>Membership and advertising can improve visibility, but can never buy verification, ratings or trust badges.</p><div class="badge-row hero-badges">${(p?.badges||[]).length?(p.badges||[]).map(b=>`<span class="trust-badge">${esc(b)}</span>`).join(''):'<span class="muted">Your earned badges will appear here.</span>'}</div></div><div class="section-title compact"><div><span class="section-kicker">Membership</span><h2>Choose what fits your business</h2></div></div><div class="tier-scroll"><div class="tier-card"><small>Start small</small><h3>Start</h3><div class="tier-price">R49<span>/mo</span></div><p>2 services · 2 areas · buy Boosts when needed</p></div><div class="tier-card featured"><span class="mini-pill">Sweet spot</span><h3>Grow</h3><div class="tier-price">R99<span>/mo</span></div><p>5 services · 5 areas · 2 Boosts · useful insights</p></div><div class="tier-card"><small>For busier businesses</small><h3>Pro</h3><div class="tier-price">R169<span>/mo</span></div><p>10 services · 10 areas · 6 Boosts · full insights</p></div></div><div class="growth-grid"><div class="growth-card">${icon('promote')}<div><span class="section-kicker">Promote your services</span><h3>Neighbourly Boost</h3><p>Promote one service in one area for a set period. Simple, local and clearly marked.</p><div class="boost-balance"><b>${p?.boosts||0}</b><span>Boosts available</span></div><button class="btn primary" data-action="createPromotion" ${!(p?.boosts>0)?'disabled':''}>Use 1 Boost</button></div></div><div class="growth-card soft-card">${icon('promote')}<div><span class="section-kicker">In-platform advertising</span><h3>Neighbourly Spotlight</h3><p>A dedicated promoted-provider section. Every placement says <b>Promoted</b>, while badges remain earned.</p></div></div></div><details class="info-drawer"><summary>See the full badge family <span>→</span></summary><div class="badge-row">${['Skilled by Experience','Qualified & Verified','Registered Professional','Highly Rated','Reliable Neighbour','Quick to Reply','Customer Favourite','Repeat Choice','New to Neighbourly'].map(b=>`<span class="trust-badge">${esc(b)}</span>`).join('')}</div><p>Badges describe verified facts or genuine platform activity. They cannot be selected or bought.</p></details><details class="info-drawer"><summary>Annual & founding options <span>→</span></summary><p>Working launch idea: annual membership at roughly 10 months for the price of 12, plus a reduced Founding Neighbour rate for the earliest approved providers while their membership stays active. Final commercial pricing will be confirmed before launch.</p></details></section>`)}

function communityEvents(publicMode=false){prunePastEvents(state);const list=filteredEvents();const areas=['All',...new Set((state.events||[]).map(e=>e.area))],cats=['All',...new Set((state.events||[]).map(e=>e.category))],months=['All',...new Set((state.events||[]).map(e=>monthKey(e.startsAt)))];const content=`<section class="screen events-screen">${topbar('Community events','What’s happening around the neighbourhood.')}<div class="events-hero"><span class="section-kicker">Nearby & worth knowing about</span><h1>What’s on?</h1><p>Find something by area, category or month — or add something your neighbourhood should know about.</p>${!publicMode&&state.role?`<button class="btn primary" data-action="addEvent">List an event</button>`:''}</div><details class="filter-drawer"><summary>${icon('search','tiny')}<span>Filter events</span><b>+</b></summary><div class="filter-row"><label><small>Area</small><select id="eventArea">${areas.map(x=>`<option value="${esc(x)}" ${state.ui.eventArea===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label><small>Category</small><select id="eventCategory">${cats.map(x=>`<option value="${esc(x)}" ${state.ui.eventCategory===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label><small>Month</small><select id="eventMonth">${months.map(x=>`<option value="${esc(x)}" ${state.ui.eventMonth===x?'selected':''}>${x==='All'?'Any month':new Date(x+'-01').toLocaleDateString(undefined,{month:'long',year:'numeric'})}</option>`).join('')}</select></label></div></details><div class="section-title compact"><div><span class="section-kicker">Coming up</span><h2>Upcoming events</h2></div></div><div id="eventResults" class="events-grid">${eventCards(list)}</div><p class="section-note">Past events disappear automatically. If a listing feels misleading or inappropriate, report it and the Sisters Help Desk will take a look.</p>${publicMode?`<button class="btn ghost" data-nav="publicHome">Back home</button>`:''}</section>`;return shell(content,publicMode?null:undefined)}
function filteredEvents(){return (state.events||[]).filter(e=>e.status!=='removed'&&(state.ui.eventArea==='All'||e.area===state.ui.eventArea)&&(state.ui.eventCategory==='All'||e.category===state.ui.eventCategory)&&(state.ui.eventMonth==='All'||monthKey(e.startsAt)===state.ui.eventMonth)).sort((a,b)=>new Date(a.startsAt)-new Date(b.startsAt))}
function eventCards(list){return list.length?list.map(e=>{const d=new Date(e.startsAt);return `<article class="card event-card"><div class="date-tile"><span>${d.toLocaleDateString(undefined,{month:'short'})}</span><b>${d.getDate()}</b><span>${shortTime(e.startsAt)}</span></div><div class="grow"><h3>${esc(e.title)}</h3><p>${esc(e.details)}</p><div class="event-meta"><span>${esc(e.area)}</span><span>${esc(e.category)}</span><span>Listed by ${esc(e.createdBy||'Neighbourly member')}</span></div>${state.role&&state.role!=='admin'?`<button class="btn ghost small" data-action="reportEvent" data-id="${e.id}">Report this event</button>`:''}</div></article>`}).join(''):`<div class="card empty"><h3>No events match those filters</h3><p>Try another area, category or month.</p></div>`}
function updates(){const list=[...(state.updates||[])].sort((a,b)=>b.createdAt-a.createdAt);return shell(`<section class="screen narrow updates-screen">${topbar('Neighbourly updates','Important notes, maintenance and good news.')}<div class="updates-intro"><span class="section-kicker">From Neighbourly</span><h1>Worth knowing.</h1><p>If something changes, goes wrong, gets fixed or deserves celebrating, we’ll keep you in the loop here.</p></div><div class="update-stream">${list.length?list.map(u=>`<article class="update-row ${esc(u.type)}"><span class="update-dot"></span><div><small>${dateText(u.createdAt)}</small><h3>${esc(u.title)}</h3><p>${esc(u.body)}</p></div></article>`).join(''):`<div class="quiet-empty"><span>${icon('update')}</span><div><b>Nothing to report.</b><small>That’s usually a good thing.</small></div></div>`}</div></section>`)}

function helpDesk(){return shell(`<section class="screen narrow helpdesk-page">${topbar('Sisters Help Desk','Real people. Real support.')}<div class="helpdesk-hero"><img src="sisters-help-desk.png" alt="Illustration of the Sisters Help Desk"><div><span class="section-kicker">You’re not alone</span><h1>We’re here when you need us.</h1><p>Questions, order issues, account help or something that just doesn’t feel right — tell us what’s going on and we’ll take a fair look.</p><button class="btn primary" data-action="reportGeneral">Get support</button></div></div><div class="helpdesk-grid"><button data-action="reportGeneral">${icon('services')}<span><b>Order or service issue</b><small>Bookings, service problems, refunds or no-shows.</small></span></button><button data-action="reportGeneral">${icon('safety')}<span><b>Something feels unsafe or wrong</b><small>Fraud, scams, harassment, threats or anything worrying.</small></span></button><button data-action="reportGeneral">${icon('profile')}<span><b>Account or app help</b><small>Login, profile, verification or technical questions.</small></span></button><button data-nav="updates">${icon('update')}<span><b>Neighbourly updates</b><small>Maintenance, important notes and good news.</small></span></button></div><div class="helpdesk-promise"><span>♥</span><div><b>Kind people. Fair process.</b><small>You can disagree, complain or ask questions. We’ll listen without judging first.</small></div></div></section>`,'helpDesk')}

function profile(){const a=currentAccount(),p=currentProvider();return shell(`<section class="screen narrow profile-screen">${topbar('Profile','Your Neighbourly details and support.')}<div class="profile-hero"><div class="profile-avatar">${initials(a?`${a.first} ${a.last}`:'Neighbour')}</div><div><span class="section-kicker">${p?'Service provider':'Customer'}</span><h1>${esc(a?`${a.first} ${a.last}`:'Neighbour')}</h1><p>${esc(a?.area||'')}</p><div class="profile-chips">${p?`<span>Provider ID · <b>${esc(p.providerId)}</b></span>`:''}${a?.identityVerified?'<span class="verified">✓ Identity confirmed</span>':'<span>Identity check needed</span>'}</div></div></div>${!a?.identityVerified?`<button class="btn primary full" data-action="demoVerifyIdentity">Start identity check</button>`:''}<div class="profile-menu-grid">${p?`<button data-nav="providerFeatures">${icon('home')}<span><b>App features</b><small>What you can do</small></span></button><button data-nav="providerReady">${icon('badge')}<span><b>Neighbourly Ready</b><small>Training & refreshers</small></span></button><button data-nav="providerGrowth">${icon('promote')}<span><b>Reach more neighbours</b><small>Membership & visibility</small></span></button>`:`<button data-action="customerSafetyGuide">${icon('safety')}<span><b>Stay safe</b><small>Simple safety guide</small></span></button>`}<button data-nav="communityEvents">${icon('event')}<span><b>Events</b><small>What’s on nearby</small></span></button><button data-nav="updates">${icon('update')}<span><b>Updates</b><small>Notes from Neighbourly</small></span></button><button data-action="trustedContact">${icon('share')}<span><b>Trusted contact</b><small>For service sharing</small></span></button></div><div class="profile-support">${sistersSupportCard()}</div><details class="info-drawer"><summary>Policies & account <span>→</span></summary><div class="stack">${p?`<a class="btn soft link-btn" href="neighbourly-quick-start-guide.pdf" target="_blank" rel="noopener">Download Quick Start Guide</a>`:''}<button class="btn soft" data-action="showPolicies">Community, safety & food policies</button><button class="btn ghost" data-action="signout">Sign out</button></div></details></section>`,'profile')}

function adminLogin(){return shell(`<section class="screen narrow admin-login">${topbar('Sisters Help Desk','Private admin access')}<div class="admin-hero"></div><div class="card"><form id="adminLoginForm" class="form"><div class="field"><label>Desk login<input name="user" autocomplete="username"></label></div><div class="field"><label>Password<input name="password" type="password"></label></div><div class="form-error" id="adminError"></div><button class="btn primary" type="submit">Open Sisters Help Desk</button></form></div><div class="soft-note">Prototype only: production admin access needs real server-side roles, MFA and audit logging.</div></section>`)}
function adminHome(){const pending=state.providers.filter(p=>p.applicationStatus==='ready_for_review'&&p.status!=='approved').length,open=state.reports.filter(r=>r.status!=='closed').length,live=state.providers.filter(p=>p.status==='approved').length;return shell(`<section class="screen admin">${topbar('Sisters Help Desk','Real people. Real support.')}<div class="stat-grid admin-stats"><div class="stat-card"><b>${pending}</b><span>Ready for review</span></div><div class="stat-card"><b>${open}</b><span>Open reports</span></div><div class="stat-card"><b>${live}</b><span>Live providers</span></div><div class="stat-card"><b>${state.events.length}</b><span>Upcoming events</span></div></div><div class="section-title"><h2>Needs a sister’s eye</h2></div><div class="stack">${pending?`<button class="attention-card" data-nav="adminApplications">${icon('applications')}<div><b>${pending} application${pending>1?'s':''} ready</b><small>Onboarding is complete — verification comes next.</small></div></button>`:''}${open?`<button class="attention-card" data-nav="adminReports">${icon('report')}<div><b>${open} open report${open>1?'s':''}</b><small>Review fairly and proportionately.</small></div></button>`:''}${!pending&&!open?`<div class="card empty mini"><p>All clear for now </p></div>`:''}</div><div class="card-actions"><button class="btn secondary" data-action="postUpdate">Post an update</button><button class="btn secondary" data-action="adminAddEvent">Add community event</button><button class="btn secondary" data-nav="adminEvents">Manage events</button><button class="btn secondary" data-nav="adminAppeals">Appeals (${(state.appeals||[]).filter(a=>a.status==='pending').length})</button></div><div class="admin-principle"><b>Firm but fair</b><p>Guidance and proportionate restrictions come before removal in ordinary cases. Grave or repeated abuse can justify stronger action after fair review.</p></div></section>`,'adminHome')}
function verificationRows(p){const rows=[['Identity verification','identityVerified'],[p.credentialPath==='qualified'?'Qualification verification':p.credentialPath==='registered'?'Registration verification':'Experience verification','credentialVerified'],['Category/service check','categoryVerified']];if(p.siteVisitRequired)rows.push(['Site visit','siteVisitDone']);return `<div class="verify-grid">${rows.map(([label,key])=>`<div class="verify-row"><div><b>${esc(label)}</b><small>${p[key]?'Complete':'Required before approval'}</small></div><button class="btn ${p[key]?'secondary':'primary'} small" data-action="toggleVerify" data-id="${p.providerId}" data-key="${key}">${p[key]?'Undo':'Mark complete'}</button></div>`).join('')}</div>`}
function eligibleForApproval(p){return !!(p.onboardingPassed&&p.identityVerified&&p.credentialVerified&&p.categoryVerified&&(!p.siteVisitRequired||p.siteVisitDone))}
function adminApplications(){const apps=state.providers.filter(p=>['ready_for_review','changes'].includes(p.applicationStatus)||(p.status==='approved'&&!p.id.startsWith('seed-')));return shell(`<section class="screen admin">${topbar('Provider applications','Onboarding first, verification second, approval last.')}<div class="stack">${apps.length?apps.map(p=>`<article class="card"><div class="request-head"><div><h3>${esc(p.name)}</h3><p>${esc(p.providerId)} · ${esc(p.area)} · ${esc(p.category)}</p></div>${statusPill(p.status==='approved'?'approved':p.applicationStatus)}</div><div class="application-summary"><b>${esc(p.service)}</b><span>${moneySafe(p.price)}</span><p>${esc(p.about)}</p><small>${esc(p.experience||'')}</small></div><div class="privacy-banner"><b>Neighbourly Ready: ${p.onboardingPassed?'Passed ✓':'Not passed'}</b><span>Passing training never bypasses verification.</span></div>${p.status!=='approved'?verificationRows(p):''}${p.status!=='approved'?`<div class="card-actions"><button class="btn primary small" data-action="approveProvider" data-id="${p.providerId}" ${eligibleForApproval(p)?'':'disabled'}>Approve & go live</button><button class="btn secondary small" data-action="changesProvider" data-id="${p.providerId}">Needs changes</button></div>${!eligibleForApproval(p)?`<div class="soft-note">Approval stays locked until every required check is complete.</div>`:''}`:`<span class="verified">✓ Live on Neighbourly</span>`}</article>`).join(''):`<div class="card empty"><h3>No applications ready</h3><p>Only providers who pass Neighbourly Ready move into this review queue.</p></div>`}</div></section>`,'adminApplications')}
function adminReports(){return shell(`<section class="screen admin">${topbar('Reports & cases','Kind community. Fair process. Proportionate consequences.')}<div class="stack">${state.reports.length?state.reports.map(r=>`<article class="card"><div class="request-head"><div><h3>${esc(r.reason)}</h3><p>Reported by ${esc(r.fromName||'Neighbour')} · ${dateText(r.createdAt)}</p></div>${statusPill(r.status||'awaiting')}</div><div class="privacy-banner"><b>About: ${esc(r.targetLabel||'General app/support issue')}</b><span>${r.targetType==='account'||r.targetAccountId?'Account action available after review.':r.targetType==='event'?'This report concerns a community event.':'No person is targeted by this report.'}</span></div><p class="muted">${esc(r.details)}</p>${r.status!=='closed'?(r.targetAccountId||r.targetProviderId?`<div class="card-actions"><button class="btn secondary small" data-action="reportAction" data-id="${r.id}" data-level="guidance">Guidance</button><button class="btn secondary small" data-action="reportAction" data-id="${r.id}" data-level="warning">Warning</button><button class="btn secondary small" data-action="reportAction" data-id="${r.id}" data-level="final_warning">Final warning</button><button class="btn secondary small" data-action="reportAction" data-id="${r.id}" data-level="restriction">7-day restriction</button><button class="btn danger small" data-action="confirmRemoval" data-id="${r.id}">Permanent removal</button></div>`:r.targetType==='event'?`<div class="card-actions"><button class="btn danger small" data-action="removeEventFromReport" data-id="${r.id}">Remove event</button><button class="btn secondary small" data-action="closeReportGeneral" data-id="${r.id}">Keep event & close</button></div>`:`<button class="btn primary small" data-action="closeReportGeneral" data-id="${r.id}">Mark reviewed</button>`):''}${r.outcome?`<div class="soft-note">Outcome: ${esc(r.outcome)}</div>`:''}</article>`).join(''):`<div class="card empty"><h3>No reports right now</h3><p>That’s a good neighbourhood day.</p></div>`}</div></section>`,'adminReports')}
function adminPeople(){const customers=state.accounts.filter(a=>a.role==='customer'),providers=state.providers.filter(p=>!p.id.startsWith('seed-'));return shell(`<section class="screen admin">${topbar('People','Customers, providers and account status.')}<div class="section-title"><h2>Customers</h2><span class="count-pill">${customers.length}</span></div><div class="stack">${customers.map(c=>`<div class="card person-row"><div class="avatar">${initials(`${c.first} ${c.last}`)}</div><div><b>${esc(c.first+' '+c.last)}</b><small>${esc(c.area)} · ${c.identityVerified?'Identity confirmed':'Identity pending'} · ${esc(c.accountStatus||'active')}</small></div></div>`).join('')}</div><div class="section-title"><h2>Providers</h2><span class="count-pill">${providers.length}</span></div><div class="stack">${providers.map(p=>`<div class="card person-row"><div class="avatar">${initials(p.name)}</div><div><b>${esc(p.name)}</b><small>${esc(p.providerId)} · ${esc(p.status||'pending')}</small></div></div>`).join('')}</div></section>`,'adminPeople')}
function adminSettings(){return shell(`<section class="screen admin narrow">${topbar('Desk settings','Policy principles for the prototype.')}<div class="card policy-card"><h3>Community enforcement</h3><p>Account removal is the last normal step. Guidance, warnings and temporary restrictions should be proportionate to the behaviour. Severe safety issues can justify immediate protective restriction while reviewed.</p></div><div class="card policy-card"><h3>Food orders</h3><p>Food is not returnable for simple change of mind or taste preference once supplied. Genuine unsafe, incorrect or materially defective food concerns must still be handled fairly and applicable consumer rights remain.</p></div><div class="card policy-card"><h3>Identity & safety</h3><p>Customers and providers should be identity-verified before real-world services. Do not expose ID documents to other users. Production should use secure identity verification and minimal retention rather than storing raw ID copies indefinitely.</p></div><div class="card policy-card"><h3>Advertising</h3><p>Trust is earned. Reach can be purchased. Promotions must be clearly marked and cannot buy verification, ratings or trust badges.</p></div><div class="card policy-card"><h3>Production security boundary</h3><p>Real identity checks, payment controls, device-risk signals, background notifications and secure ban-evasion matching require the production backend. This prototype deliberately does not store raw ID copies.</p></div><div class="card policy-card"><h3>Audit trail</h3><p>Important admin decisions should record who acted, what changed, when and why. This prototype has ${state.auditLog?.length||0} recorded admin actions.</p></div><button class="btn secondary" data-action="signout">Close Sisters Help Desk</button></section>`,'adminSettings')}

function render(){const q=new URLSearchParams(location.search);if(q.get('admin')==='sisters'&&state.role!=='admin'&&state.route==='publicHome')state.route='adminLogin';const routes={publicHome,loginChoice,loginForm,joinChoice,joinCustomer:()=>baseSignup('customer'),joinProvider:()=>baseSignup('provider'),customerHome,findHelp,customerFavourites,customerServices,providerHome,providerHow,providerApplication,providerRequests,providerCustomers,providerServices,providerFeatures,providerReady,sectionQuiz,categoryReady,categoryReadyQuiz,finalReadyIntro,finalReadyQuiz,providerGrowth,communityEvents,publicEvents:()=>communityEvents(true),updates,helpDesk,profile,adminLogin,adminHome,adminApplications,adminReports,adminPeople,adminEvents,adminAppeals,adminSettings};const customerRoutes=new Set(['customerHome','findHelp','customerFavourites','customerServices']);const providerRoutes=new Set(['providerHome','providerHow','providerApplication','providerRequests','providerCustomers','providerServices','providerFeatures','providerReady','sectionQuiz','categoryReady','categoryReadyQuiz','finalReadyIntro','finalReadyQuiz','providerGrowth']);const adminRoutes=new Set(['adminHome','adminApplications','adminReports','adminPeople','adminEvents','adminAppeals','adminSettings']);if(customerRoutes.has(state.route)&&state.role!=='customer')state.route='publicHome';if(providerRoutes.has(state.route)&&state.role!=='provider')state.route='publicHome';if(adminRoutes.has(state.route)&&state.role!=='admin')state.route='adminLogin';if(['communityEvents','updates','helpDesk','profile'].includes(state.route)&&!state.role)state.route='publicHome';app.innerHTML=(routes[state.route]||publicHome)();bind();if(state.route==='findHelp')renderFindResults();if(state.route==='communityEvents')renderEventResults()}
function bind(){
 $$('[data-nav]').forEach(el=>el.addEventListener('click',()=>nav(el.dataset.nav)));
 $('#signupForm')?.addEventListener('submit',handleSignup);$('#loginForm')?.addEventListener('submit',handleLogin);$('#providerApplicationForm')?.addEventListener('submit',handleProviderApplication);$('#adminLoginForm')?.addEventListener('submit',handleAdminLogin);$('#sectionQuizForm')?.addEventListener('submit',handleSectionQuiz);$('#categoryQuizForm')?.addEventListener('submit',handleCategoryQuiz);$('#finalReadyForm')?.addEventListener('submit',handleFinalQuiz);
 $('#providerSearch')?.addEventListener('input',e=>{state.ui.search=e.target.value;persist();renderFindResults()});$('#categoryFilter')?.addEventListener('change',e=>{state.ui.category=e.target.value;persist();renderFindResults()});$('#areaFilter')?.addEventListener('change',e=>{state.ui.area=e.target.value;persist();renderFindResults()});
 $('#eventArea')?.addEventListener('change',e=>{state.ui.eventArea=e.target.value;persist();renderEventResults()});$('#eventCategory')?.addEventListener('change',e=>{state.ui.eventCategory=e.target.value;persist();renderEventResults()});$('#eventMonth')?.addEventListener('change',e=>{state.ui.eventMonth=e.target.value;persist();renderEventResults()});
 bindDynamic();
}
function renderEventResults(){if($('#eventResults')){$('#eventResults').innerHTML=eventCards(filteredEvents());bindDynamic()}}

async function handleSignup(e){e.preventDefault();const f=e.currentTarget,fd=new FormData(f),role=f.dataset.role,first=fd.get('first').trim(),last=fd.get('last').trim(),email=fd.get('email').trim().toLowerCase(),phone=fd.get('phone').trim(),area=fd.get('area').trim(),password=fd.get('password'),err=$('#signupError');if(!first||!last||!/^\S+@\S+\.\S+$/.test(email)||phone.replace(/\D/g,'').length<9||!area||password.length<8||!fd.get('community')){err.textContent='Almost there — complete every field and tick the community agreement.';err.classList.add('show');return}if((state.bannedPeople||[]).some(b=>b.email===email||normPhone(b.phone)===normPhone(phone))){state.auditLog.push({t:Date.now(),action:'Blocked rejoin attempt',details:`${email} · ${normPhone(phone)}`,actor:'System'});persist();err.textContent='We can’t approve this signup automatically because these details match a permanently removed account. If you believe this is a mistake, use “Appeal a Neighbourly decision” on the home page.';err.classList.add('show');return}if(state.accounts.some(a=>a.email===email)){err.textContent='That email is already part of Neighbourly.';err.classList.add('show');return}const passwordHash=await hashText(password),id=uid('acct');const account={id,role,first,last,email,phone,area,passwordHash,identityVerified:false,createdAt:Date.now(),accountStatus:'active'};if(role==='provider'){account.providerId=uniqueProviderId();state.providers.push({id:uid('prov'),providerId:account.providerId,name:`${first} ${last}`,area,category:'',service:'',price:'Ask for a quote',rating:0,reviews:0,verified:false,identityVerified:false,about:'',areas:[area],availability:'',status:'pending',applicationStatus:null,credentialVerified:false,categoryVerified:false,siteVisitRequired:false,siteVisitDone:false,onboardingPassed:false,badges:[],membership:'Start',boosts:0,paused:false,applicationUpdates:[],gallery:[],membershipBreakHistory:[]})}state.accounts.push(account);state.currentAccountId=id;state.role=role;state.route=role==='provider'?'providerHow':'customerHome';persist();render();toast(role==='provider'?'Provider account created ':'Welcome to the neighbourhood ♥')}
async function handleLogin(e){e.preventDefault();const fd=new FormData(e.currentTarget),identifier=fd.get('identifier').trim().toLowerCase(),password=fd.get('password'),hash=await hashText(password);let a=state.accounts.find(x=>(x.email===identifier||(x.providerId&&x.providerId.toLowerCase()===identifier))&&x.role===state.loginRole);if(!a||!((a.demoPassword&&password===a.demoPassword)||(a.passwordHash&&a.passwordHash===hash))){$('#loginError').textContent='We couldn’t match those details. Check them and try again.';$('#loginError').classList.add('show');return}if(a.accountStatus==='permanently_removed'){$('#loginError').textContent='This account was permanently removed. If you believe this was a mistake, use the appeal option on the Neighbourly home page.';$('#loginError').classList.add('show');return}state.currentAccountId=a.id;state.role=a.role;state.route=a.role==='provider'?'providerHome':'customerHome';persist();render();toast(`Welcome back, ${a.first} `)}
