 $$('[data-action="viewProvider"]').forEach(b=>b.onclick=()=>showProvider(b.dataset.id));
 $$('[data-action="requestService"]').forEach(b=>b.onclick=()=>requestModal(b.dataset.id));
 $$('[data-action="cancelRequest"]').forEach(b=>b.onclick=()=>{const r=state.requests.find(x=>x.id===b.dataset.id);if(r){r.status='cancelled';persist();render();toast('Request cancelled')}});
 $$('[data-action="acceptRequest"]').forEach(b=>b.onclick=()=>{const a=currentAccount();if(a?.accountStatus==='restricted'){toast('New requests are paused while your account is restricted');return}const r=state.requests.find(x=>x.id===b.dataset.id);if(r){r.status='accepted';r.serviceCode=code4();persist();render();toast('Booked — Service Code created ✓')}});
