function trainingBack(){const t=trainingState();if(t.screen>0)t.screen--;else if(t.section>0){t.section--;t.screen=trainingSections[t.section].screens.length-1}persist();nav('providerReady')}
function trainingNext(){const t=trainingState(),sec=trainingSections[t.section];if(t.screen<sec.screens.length-1){t.screen++;persist();nav('providerReady')}else nav('sectionQuiz')}
function nextTrainingSection(){const t=trainingState();if(t.section<trainingSections.length-1){t.section++;t.screen=0;persist();nav('providerReady')}else{const p=currentProvider();if(categoryModuleFor(p)&&!t.categoryPassed?.[p.category])nav('categoryReady');else nav('finalReadyIntro')}}
function retrySection(){const t=trainingState();t.screen=0;persist();nav('providerReady')}
function finishReady(){const p=currentProvider(),t=trainingState();if(!p||!t.finalPassed)return;p.onboardingPassed=true;p.applicationStatus='ready_for_review';p.applicationUpdates=p.applicationUpdates||[];p.applicationUpdates.push({t:Date.now(),text:'Neighbourly Ready completed — sent to Sisters Help Desk for review'});persist();nav('providerHome');toast('You’re Neighbourly Ready ✓')}
function showProvider(id){const p=state.providers.find(x=>x.providerId===id);if(!p)return;const photos=(p.gallery||[]).map(x=>`<figure><img src="${x.dataUrl}" alt="Provider work example"><figcaption>${esc(x.caption||'Work example')}</figcaption></figure>`).join('');htmlModal(`${esc(p.name)} · ${esc(p.service)}`,`<p class="muted">${esc(p.about)}</p><div class="provider-meta"><span>${esc((p.areas||[]).join(', '))}</span><span>${esc(p.availability)}</span><span>${moneySafe(p.price)}</span><span>★ ${esc(p.rating)} (${esc(p.reviews)})</span></div><div class="badge-row">${(p.badges||[]).map(b=>`<span class="trust-badge">${esc(b)}</span>`).join('')}</div>${photos?`<h3>Work gallery</h3><div class="work-gallery public">${photos}</div>`:''}<div class="card-actions"><button class="btn primary" id="profileRequest">Request service</button>${state.role==='customer'?`<button class="btn secondary" id="profileReport">Report provider</button>`:''}</div>`,()=>{$('#profileRequest')?.addEventListener('click',()=>{closeModal();requestModal(id)});$('#profileReport')?.addEventListener('click',()=>{closeModal();reportModal({providerId:id})})})}
function requestModal(providerId){const p=state.providers.find(x=>x.providerId===providerId),a=currentAccount();if(!p||!a)return;if(a.accountStatus==='restricted'){modal('Account temporarily restricted','You can still view Neighbourly and contact the Sisters Help Desk, but new service requests are paused while this restriction is active.');return}if(!a.identityVerified){modal('Identity check needed','Before a real-world service request can be sent, customers need identity confirmation. In production this will use a secure identity-verification provider rather than storing raw ID copies in the app.','Go to profile',()=>nav('profile'));return}formModal('Request a service',`<p class="muted">You’re requesting <b>${esc(p.service)}</b> from ${esc(p.name)}.</p><div class="field"><label>Preferred date<input name="date" type="date" required></label></div><div class="field"><label>Anything they should know?<textarea name="note" maxlength="300"></textarea></label></div>${connectionNote(true)}<button class="btn primary" type="submit">Send request</button>`,fd=>{state.requests.push({id:uid('req'),providerId,providerName:p.name,customerId:a.id,customerName:`${a.first} ${a.last}`,service:p.service,date:fd.get('date')||futureISO(2),note:fd.get('note').trim(),status:'awaiting',createdAt:Date.now(),customerRating:null,extraWork:null,messages:[]});persist();closeModal();toast('Request sent ✓');setTimeout(()=>nav('customerServices'),250)})}
function ratingModal(requestId){formModal('How did it go?',`<p class="muted">Your honest feedback helps the neighbourhood.</p><div class="field"><label>Rating<select name="rating" required><option value="">Choose stars</option>${[5,4,3,2,1].map(n=>`<option value="${n}">${'★'.repeat(n)} ${n}/5</option>`).join('')}</select></label></div><div class="field"><label>Quick tags (optional)</label><div class="tag-checks"><label><input type="checkbox" name="tag" value="On time"> On time</label><label><input type="checkbox" name="tag" value="Friendly"> Friendly</label><label><input type="checkbox" name="tag" value="Great work"> Great work</label><label><input type="checkbox" name="tag" value="Good value"> Good value</label></div></div><div class="field"><label>Short review<textarea name="review" maxlength="280"></textarea></label></div><button class="btn primary" type="submit">Share my review</button>`,fd=>{const r=state.requests.find(x=>x.id===requestId);if(!r||!fd.get('rating'))return;r.customerRating=Number(fd.get('rating'));r.review=fd.get('review').trim();r.reviewTags=fd.getAll('tag');const p=state.providers.find(x=>x.providerId===r.providerId);if(p){const total=p.rating*p.reviews+r.customerRating;p.reviews+=1;p.rating=Math.round((total/p.reviews)*10)/10}persist();closeModal();render();toast('Thanks — review shared ♥')})}
function toggleCustomerFav(customerId){const p=currentProvider();if(!p)return;const i=state.favourites.customers.findIndex(x=>x.providerId===p.providerId&&x.customerId===customerId);if(i>=0)state.favourites.customers.splice(i,1);else state.favourites.customers.push({providerId:p.providerId,customerId});persist();render();toast(i>=0?'Removed from favourites':'Favourite customer saved ♥')}
function customerNoteModal(customerId){const p=currentProvider(),c=state.accounts.find(a=>a.id===customerId);if(!p||!c)return;const key=`${p.providerId}:${customerId}`,existing=state.customerNotes[key]||{};formModal(`Private note · ${c.first}`,`<div class="privacy-banner"><b>Only you can see this</b><span>Keep notes factual and related to working together. Do not record discriminatory or unnecessarily sensitive personal information.</span></div><div class="field"><label>Would you work with this customer again?<select name="rating"><option value="">Not rated</option>${[5,4,3,2,1].map(n=>`<option value="${n}" ${Number(existing.rating)===n?'selected':''}>${n}/5</option>`).join('')}</select></label></div><div class="field"><label>Private note<textarea name="note" maxlength="300">${esc(existing.note||'')}</textarea></label></div><button class="btn primary" type="submit">Save private note</button>`,fd=>{state.customerNotes[key]={rating:Number(fd.get('rating'))||null,note:fd.get('note').trim(),updatedAt:Date.now()};persist();closeModal();render();toast('Private note saved')})}
function addExtraModal(requestId){formModal('Add extra work',`<p class="muted">Ask your provider before anything changes.</p><div class="field"><label>What would you like added?<textarea name="description" required maxlength="300"></textarea></label></div><button class="btn primary" type="submit">Send extra work request</button>`,fd=>{const r=state.requests.find(x=>x.id===requestId);if(!r)return;r.extraWork={status:'customer_requested',description:fd.get('description').trim(),requestedAt:Date.now()};persist();closeModal();render();toast('Extra work request sent')})}
function reviewExtraModal(requestId){const r=state.requests.find(x=>x.id===requestId);if(!r?.extraWork)return;formModal('Review extra work',`<p class="muted">${esc(r.extraWork.description)}</p><div class="field"><label>Extra cost (R)<input name="cost" type="number" min="0" step="1" required></label></div><div class="field"><label>Any updated timing or note?<textarea name="note" maxlength="240"></textarea></label></div><button class="btn primary" type="submit">Send change for customer confirmation</button>`,fd=>{r.extraWork.status='provider_proposed';r.extraWork.addedCost=Number(fd.get('cost'))||0;r.extraWork.providerNote=fd.get('note').trim();persist();closeModal();render();toast('Sent to customer for confirmation')})}
function setExtraStatus(id,status,msg){const r=state.requests.find(x=>x.id===id);if(r?.extraWork){r.extraWork.status=status;r.extraWork.updatedAt=Date.now();persist();render();toast(msg)}}
function safetyModal(requestId){const r=state.requests.find(x=>x.id===requestId),a=currentAccount();if(!r||!a)return;const timer=(r.safetyTimers||{})[a.id],contact=a.trustedContact;formModal('Service safety',`<div class="privacy-banner"><b>Service Code</b><span>Use this with the booking details to confirm the correct service meeting.</span></div><div class="service-code">${esc(r.serviceCode||'----')}</div>${timer?`<div class="${timer.overdue&&!timer.checkedOut?'danger-note':'soft-note'}">${timer.checkedOut?'Checked out safely ✓':timer.overdue?'Your expected finish time has passed. Please check out when you are safe.':`Expected finish: ${dateText(timer.expectedAt)} · ${shortTime(timer.expectedAt)}`}</div>`:''}<div class="stack" style="margin-top:14px"><button type="button" class="btn secondary" data-safety="checkin">${r.checkins?.[a.id]?'Checked in ✓':'Check in'}</button><button type="button" class="btn secondary" data-safety="timer">${timer&&!timer.checkedOut?'Update safety time':'Set expected finish time'}</button><button type="button" class="btn secondary" data-safety="share">Share service details${contact?` with ${esc(contact.name)}`:''}</button>${timer&&!timer.checkedOut?`<button type="button" class="btn primary" data-safety="checkout">Check out safely</button>`:''}<button type="button" class="btn secondary" data-safety="report">Report a problem</button></div><p class="muted">Neighbourly is not an emergency service. If someone is in immediate danger, contact appropriate emergency help first. Safety timers in this prototype are checked when the app is open; production will use secure notifications.</p>`,()=>{});$$('[data-safety]').forEach(b=>b.onclick=async()=>{const action=b.dataset.safety;if(action==='checkin'){r.checkins=r.checkins||{};r.checkins[a.id]=Date.now();if(a.role==='provider'&&r.status==='accepted')r.status='in_progress';persist();closeModal();render();toast('Checked in ✓')}else if(action==='timer'){closeModal();setSafetyTimerModal(requestId)}else if(action==='share'){await shareServiceDetails(requestId)}else if(action==='checkout'){r.safetyTimers=r.safetyTimers||{};if(r.safetyTimers[a.id]){r.safetyTimers[a.id].checkedOut=true;r.safetyTimers[a.id].checkedOutAt=Date.now();r.safetyTimers[a.id].overdue=false}persist();closeModal();render();toast('Checked out safely ✓')}else{closeModal();reportModal({requestId})}})}
function pauseProviderModal(){const p=currentProvider();if(!p)return;if(p.membershipBreakUntil&&new Date(p.membershipBreakUntil).getTime()>Date.now()){toast('Your membership break controls availability until your return date.');return}if(p.paused){p.paused=false;p.pauseReturn=null;p.awayMessage=null;p.hideFromSearch=false;persist();render();toast('Back in the neighbourhood ✓');return}formModal('Pause availability',`<p class="muted">Need a breather? Let customers know you’re away.</p><div class="field"><label>Return date (optional)<input name="return" type="date"></label></div><div class="field"><label>Away message (optional)<textarea name="message" maxlength="140" placeholder="e.g. Taking a few days off — back soon."></textarea></label></div><label class="check"><input name="hide" type="checkbox"><span>Hide me from Explore while I’m away</span></label><button class="btn primary" type="submit">Pause availability</button>`,fd=>{p.paused=true;p.pauseReturn=fd.get('return')||null;p.awayMessage=fd.get('message').trim()||null;p.hideFromSearch=!!fd.get('hide');persist();closeModal();render();toast('Taking a breather — availability paused')})}
function createPromotionModal(){const p=currentProvider();if(!p||p.boosts<1)return;formModal('Use a Neighbourly Boost',`<p class="muted">Promote one real service in one area. Paid placements are clearly marked Promoted.</p><div class="field"><label>Service<input name="service" value="${esc(p.service)}" required></label></div><div class="field"><label>Area<select name="area">${(p.areas||[]).map(a=>`<option>${esc(a)}</option>`).join('')}</select></label></div><div class="field"><label>Badge to highlight<select name="badge"><option value="">No badge</option>${(p.badges||[]).map(b=>`<option>${esc(b)}</option>`).join('')}</select></label></div><button class="btn primary" type="submit">Use 1 Boost</button>`,fd=>{p.boosts--;state.promotions.push({id:uid('promo'),providerId:p.providerId,service:fd.get('service'),area:fd.get('area'),badge:fd.get('badge'),createdAt:Date.now(),expiresAt:Date.now()+7*86400000});persist();closeModal();render();toast('Promotion live for 7 days · clearly marked Promoted')})}
function addEventModal(){const a=currentAccount();formModal('List a community event',`<div class="field"><label>Event name<input name="title" required maxlength="90"></label></div><div class="field two"><label>Area<input name="area" required value="${esc(a?.area||'')}"></label><label>Category<select name="category"><option>Community</option><option>Market</option><option>Family</option><option>Learning</option><option>Sport</option><option>Faith & community</option><option>Other</option></select></label></div><div class="field"><label>Date and time<input name="date" type="datetime-local" required></label></div><div class="field"><label>Details<textarea name="details" required maxlength="400"></textarea></label></div><label class="check"><input name="accurate" type="checkbox" required><span>I confirm this listing is genuine and the details are accurate to the best of my knowledge.</span></label><button class="btn primary" type="submit">List event</button>`,fd=>{const dt=new Date(fd.get('date'));if(!fd.get('title')||!fd.get('accurate')||isNaN(dt)||dt.getTime()<Date.now()){toast('Complete the event details and choose a future date');return}state.events.push({id:uid('event'),title:fd.get('title').trim(),area:fd.get('area').trim(),category:fd.get('category'),startsAt:dt.toISOString(),details:fd.get('details').trim(),createdBy:a?`${a.first} ${a.last}`:'Sisters Help Desk',createdById:a?.id||null,status:'active'});persist();closeModal();render();toast('Community event listed ✓')})}
function postUpdateModal(){formModal('Post a Neighbourly update',`<div class="field"><label>Update type<select name="type"><option value="info">Important note</option><option value="issue">Service issue / maintenance</option><option value="good">Good news</option></select></label></div><div class="field"><label>Title<input name="title" required maxlength="90"></label></div><div class="field"><label>Message<textarea name="body" required maxlength="500"></textarea></label></div><button class="btn primary" type="submit">Post update</button>`,fd=>{state.updates.push({id:uid('up'),type:fd.get('type'),title:fd.get('title').trim(),body:fd.get('body').trim(),createdAt:Date.now()});persist();closeModal();render();toast('Neighbourly update posted')})}
function reportModal(context={}){const a=currentAccount(),targets=reportTargetOptions(a,context),selected=reportContextValue(context,a);formModal('Sisters Help Desk',`<div class="support-modal-head"><img src="sisters-help-desk.png" alt="Illustration of the Sisters Help Desk"><div><span class="support-kicker">Real people. Real support.</span><p>Tell us what’s going on. You can disagree, complain or ask questions — we just ask everyone to communicate respectfully.</p></div></div><div class="field"><label>Who or what is this about?<select name="target" required>${targets.map(x=>`<option value="${esc(x.value)}" ${x.value===selected?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label></div><div class="field"><label>What can we help with?<select name="reason" required><option value="">Choose what fits best</option><option>Order issue</option><option>Service issue</option><option>Payment or refund issue</option><option>No-show or cancellation</option><option>Food safety or quality concern</option><option>Something feels unsafe or wrong</option><option>App or account issue</option><option>Community event issue</option><option>Something else</option></select><small>Choose “Something feels unsafe or wrong” for fraud, scams, harassment, threats, discrimination, sexual misconduct or anything else that worries you.</small></label></div><div class="field"><label>Tell us what happened<textarea name="details" required maxlength="700" placeholder="Just tell us what we need to understand."></textarea></label></div><button class="btn primary" type="submit">Send to Sisters Help Desk</button>`,fd=>{if(!fd.get('reason')||!fd.get('details').trim())return;const target=resolveReportTarget(fd.get('target'));state.reports.push({id:uid('rep'),reason:fd.get('reason'),details:fd.get('details').trim(),fromName:a?`${a.first} ${a.last}`:'Neighbour',fromId:a?.id||null,targetType:target.type,targetId:target.id,targetLabel:target.label,targetAccountId:target.accountId||null,targetProviderId:target.providerId||null,status:'awaiting',createdAt:Date.now()});persist();closeModal();toast('Thanks for telling us. We’ll take a look.')})}
function customerSafetyGuide(){modal('Stay safe with Neighbourly',`1. Check who you booked using the profile and Service Code.\n\n2. Keep important arrangements in Neighbourly where practical.\n\n3. Never share your password, banking PIN or OTP.\n\n4. Extra work belongs in the Extra Work flow so both sides agree.\n\n5. If something feels wrong, stop and get help. Neighbourly is not an emergency service.`)}
function membershipBreakModal(){const p=currentProvider();if(!p)return;if(p.membershipBreakUntil&&new Date(p.membershipBreakUntil).getTime()>Date.now()){modal('End membership break early',`Your membership break is scheduled until ${dateText(p.membershipBreakUntil)}. You can return early without a reactivation fee.`,'Return now',()=>{p.membershipBreakUntil=null;p.membershipStatus='active';p.paused=false;p.hideFromSearch=false;persist();render();toast('Back in the neighbourhood ✓')});return}const history=(p.membershipBreakHistory||[]).filter(x=>Date.now()-x.startedAt<365*86400000);if(history.length>=2){modal('Membership break limit reached','The working policy allows up to two membership breaks in a rolling 12 months. The Sisters Help Desk can help if there are exceptional circumstances.');return}formModal('Take a membership break',`<p class="muted">Life happens. A membership break keeps your profile, reviews, history and Provider ID safe while your active membership is paused.</p><div class="field"><label>Return date<input name="return" type="date" required></label></div><p class="muted">Up to 60 days, up to twice in 12 months, no reactivation fee. Your profile is removed from active search. In production, billing will pause and resume automatically on the selected date.</p><button class="btn primary" type="submit">Schedule membership break</button>`,fd=>{const d=new Date(`${fd.get('return')}T12:00:00`),max=Date.now()+60*86400000;if(isNaN(d)||d.getTime()<=Date.now()||d.getTime()>max){toast('Choose a return date within 60 days');return}p.membershipBreakHistory=history;p.membershipBreakHistory.push({startedAt:Date.now(),returnAt:d.getTime()});p.membershipBreakUntil=d.toISOString();p.membershipStatus='break';p.paused=true;p.hideFromSearch=true;persist();closeModal();render();toast('Membership break scheduled')})}
function portfolioInfo(){modal('Work gallery','Add up to three genuine work examples with short captions. Do not upload customer faces, home addresses, documents or personal information without permission. Images are compressed and stored only in this browser prototype; production will use secure storage, moderation and reporting.') }
function audit(action,details=''){state.auditLog=state.auditLog||[];state.auditLog.push({t:Date.now(),action,details,actor:'Sisters Help Desk'});persist()}
function showPolicies(){modal('Community, safety & food policies',`NEIGHBOURLY IS A KIND COMMUNITY\nCustomers, providers and the Sisters Help Desk must treat each other with respect. Complaints and disagreement are allowed. Abuse, threats, harassment, discrimination, sexual misconduct, scams and deliberate exploitation are not.\n\nFIRM BUT FAIR\nGuidance, warnings and temporary restrictions are used proportionately. Account removal is the last normal step, but severe or repeated confirmed abuse can justify permanent removal. Permanently removed users may not rejoin. Strong identity matches are reviewed carefully so shared devices, homes or surnames do not create automatic false bans.\n\nFOOD ORDERS\nSupplied food is not returnable simply because someone changed their mind or dislikes the taste. Genuine unsafe, incorrect or materially defective food concerns must be handled fairly and applicable consumer rights remain.\n\nIDENTITY & PRIVACY\nNeighbourly aims to verify both sides before real-world services without exposing ID documents to other users. Production should use secure identity verification and keep only necessary information for as long as needed.\n\nSAFETY\nKeep arrangements in Neighbourly where practical, never share passwords/PINs/OTPs, use Service Codes and report suspicious behaviour. Neighbourly is not an emergency service.\n\nCANCELLATIONS & NO-SHOWS\nBoth sides should cancel as early as reasonably possible. Repeated avoidable cancellations or no-shows can affect reliability status and may lead to proportionate account action. Genuine emergencies should be considered fairly.\n\nPERMANENT REMOVAL & REJOINING\nPermanent removal is reserved for serious or repeated confirmed breaches. A permanently removed person may not simply create a new account. Exact or strong identity matches should be reviewed, while shared addresses, devices, surnames or Wi-Fi alone are not proof. One fair appeal route should exist for mistakes.\n\nSISTERS HELP DESK\nYou may disagree with us, complain or appeal. That is not abuse. We commit to fair treatment, privacy, clear reasons for significant decisions and conflict-of-interest care. Threats, harassment or abuse toward support staff are treated under the same Community Standard.`)}
function demoVerifyIdentity(){const a=currentAccount();if(!a)return;modal('Prototype identity check','For the real app, Neighbourly should use a secure identity-verification service with ID + selfie/liveness checks and minimal data retention. This prototype will only simulate a successful check.','Simulate verification',()=>{a.identityVerified=true;const p=currentProvider();if(p)p.identityVerified=true;persist();render();toast('Prototype identity confirmed ✓')})}
function toggleVerify(providerId,key){const p=state.providers.find(x=>x.providerId===providerId);if(!p)return;p[key]=!p[key];audit('Verification updated',`${p.providerId} · ${key} · ${p[key]?'complete':'reopened'}`);p.applicationUpdates=p.applicationUpdates||[];p.applicationUpdates.push({t:Date.now(),text:`${titleCase(key.replace(/([A-Z])/g,' $1'))} ${p[key]?'completed':'reopened'}`});persist();render()}
function approveProvider(id){const p=state.providers.find(x=>x.providerId===id);if(!p||!eligibleForApproval(p))return;audit('Provider approved',p.providerId);p.status='approved';p.applicationStatus='approved';p.verified=true;p.badges=p.badges||[];const trust=p.credentialPath==='qualified'?'Qualified & Verified':p.credentialPath==='registered'?'Registered Professional':'Skilled by Experience';if(!p.badges.includes(trust))p.badges.unshift(trust);p.applicationUpdates.push({t:Date.now(),text:'Application approved — profile is live'});persist();render();toast(`${p.name} is now live ✓`)}
function changesProvider(id){const p=state.providers.find(x=>x.providerId===id);if(!p)return;audit('Provider changes requested',p.providerId);p.status='changes';p.applicationStatus='changes';p.applicationUpdates=p.applicationUpdates||[];p.applicationUpdates.push({t:Date.now(),text:'Sisters Help Desk requested changes'});persist();render();toast('Marked as needing changes')}
function confirmRemovalModal(id){const r=state.reports.find(x=>x.id===id);if(!r)return;formModal('Confirm permanent removal',`<div class="danger-note"><b>Last-step action</b><span>Permanent removal should only be used after a fair review for serious or repeated confirmed misconduct. The person will not be permitted to rejoin.</span></div><p class="muted">Target: <b>${esc(r.targetLabel||'Unknown')}</b></p><label class="check"><input name="secondReview" type="checkbox" required><span>A second review has been completed, or an urgent safety reason for proceeding is recorded.</span></label><div class="field"><label>Type REMOVE to confirm<input name="confirm" autocomplete="off" required></label></div><div class="field"><label>Decision note<textarea name="note" maxlength="500" required placeholder="Briefly record why permanent removal is proportionate."></textarea></label></div><button class="btn danger" type="submit">Permanently remove account</button>`,fd=>{if(!fd.get('secondReview')||fd.get('confirm')!=='REMOVE'||!fd.get('note').trim()){toast('Complete the review confirmation and type REMOVE');return}r.decisionNote=fd.get('note').trim();closeModal();reportAction(id,'removal')})}
function reportAction(id,level){const r=state.reports.find(x=>x.id===id);if(!r)return;const labels={guidance:'Guidance provided',warning:'Formal warning issued',final_warning:'Final warning issued',restriction:'7-day temporary restriction applied',removal:'Permanent removal after serious/repeated confirmed breach'},acct=state.accounts.find(a=>a.id===r.targetAccountId),provider=state.providers.find(p=>p.providerId===r.targetProviderId)||(acct?.providerId?state.providers.find(p=>p.providerId===acct.providerId):null);r.status='closed';r.outcome=labels[level];if(acct){acct.enforcementHistory=acct.enforcementHistory||[];acct.enforcementHistory.push({t:Date.now(),level,caseId:r.id})}if(level==='restriction'){const until=Date.now()+7*86400000;if(acct){acct.accountStatus='restricted';acct.restrictionUntil=until}if(provider){provider.previousStatus=provider.status;provider.status='restricted';provider.hideFromSearch=true;provider.restrictionUntil=until}}if(level==='removal'){if(acct){acct.accountStatus='permanently_removed';state.bannedPeople=state.bannedPeople||[];if(!state.bannedPeople.some(b=>b.accountId===acct.id))state.bannedPeople.push({accountId:acct.id,email:acct.email,phone:acct.phone,name:`${acct.first} ${acct.last}`,providerId:acct.providerId||null,previousProviderStatus:provider?.status||null,reason:r.reason,removedAt:Date.now()})}if(provider){provider.previousStatus=provider.status;provider.status='removed';provider.hideFromSearch=true}}audit('Case outcome',`${r.id} · target ${r.targetLabel||'unknown'} · ${labels[level]}`);persist();render();toast(labels[level])}

function closeModal(){document.querySelector('.modal-backdrop')?.remove();document.removeEventListener('keydown',escapeModal)}
function escapeModal(e){if(e.key==='Escape')closeModal()}
function modal(title,body,actionLabel=null,action=null){closeModal();const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="close-row"><h2>${esc(title)}</h2><button type="button">×</button></div><div class="modal-copy">${esc(body).replace(/\n/g,'<br>')}</div>${actionLabel?`<button class="btn primary" id="modalAction">${esc(actionLabel)}</button>`:''}</div>`;document.body.appendChild(wrap);wrap.querySelector('.close-row button').onclick=closeModal;wrap.onclick=e=>{if(e.target===wrap)closeModal()};if(actionLabel)$('#modalAction',wrap).onclick=()=>{closeModal();action?.()};document.addEventListener('keydown',escapeModal)}
function formModal(title,html,onSubmit){closeModal();const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="close-row"><h2>${esc(title)}</h2><button type="button">×</button></div><form class="form modal-form">${html}</form></div>`;document.body.appendChild(wrap);wrap.querySelector('.close-row button').onclick=closeModal;wrap.onclick=e=>{if(e.target===wrap)closeModal()};wrap.querySelector('form').onsubmit=e=>{e.preventDefault();onSubmit(new FormData(e.currentTarget))};document.addEventListener('keydown',escapeModal)}

if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('service-worker.js').catch(()=>{}));
render();
